programs.sol:
"""Sparse lexical-completion pulses, not a general Chinese-language detector.

The negative lexicon includes conspicuous synonym-rewriting forms (e.g. 年夜
for 大 and 小我 for 个人). After two distinct rewrite markers, further split
Chinese dictionary words receive a weak negative fallback. A few Chinese and
English collocations have separate pulses. Document markers are handled too.
Large training responses motivated the lexicon; coverage is deliberately
limited. All memory resets at document boundaries; byte tails preserve split Han.
"""
from functools import lru_cache
import cedict
import opencc
import regex
import wordnet

READS = ()
SIMPLIFY = opencc.OpenCC('t2s')
COPULA = {'is', 'are', 'was', 'were'}
BE = COPULA | {'be', 'been', 'being'}
REWRITES = {
    '年夜', '平易近', '不克不及', '喷鼻', '比力',
    '才气', '羁系', '先容', '经由过程', '小我',
}
# Responses at the end of a word split across tokens.
PULSES = {
    '经由': -3.9,
    '经由过程': -2.7,
    '小我': -4.5,
    '比力': -5.0,
    '才气': -4.5,
    '羁系': -3.7,
    '先容': -2.8,
    '喷鼻': -3.0,
    '平易': -2.2,
    '平易近': -1.4,
    '年夜': -1.1,
    '不克不及': -1.9,
    '泉源': -4.5,
    '若何': -3.8,
    '门路': -2.8,
    '卖力': -3.0,
    '造就': -2.6,
    '公里': -1.2,
    '亲切': 1.8,
    '关切': 2.4,
    '探访': 1.5,
    '洗漱': 2.2,
    '收看': 1.7,
    '各个': 1.0,
}


@lru_cache(maxsize=4096)
def verb_form(word, base):
    return word == base or base in wordnet.base_forms(word)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, prev, tail, seen = 0, '', b'', frozenset()
    else:
        _, pos, prev, tail, seen = carry
    token, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    word, before = token.strip().lower(), prev.strip().lower()
    value = 0.001
    if word == 'advantage' and verb_form(before, 'take'):
        value = 1.8
    elif word == 'to' and before in BE:
        value = 0.21
    elif word == 'that' and before in COPULA:
        value = 0.21
    elif word == 'to' and (before == 'order' or verb_form(before, 'lead')):
        value = 0.19
    elif word == 'al' and before == 'et':
        value = 0.23
    elif word == 'preview' and before == 'this':
        value = -0.38
    elif word == 'shows' and before == 'preview':
        value = -0.63
    elif word in {'page', 'pages'} and before == 'shows':
        value = -0.68
    elif token == '<think>':
        value = -0.21
    elif pos == 1 and prev == 'Title' and token == ':':
        value = -1.93
    elif token and not token.strip('·'):
        value = -0.665 if prev and not prev.strip('·') else 0.0

    joined = tail + raw
    if not token.isascii():
        text = SIMPLIFY.convert(joined.decode('utf-8', 'ignore'))
        seen = seen | {m for m in REWRITES if text.endswith(m)}
        if (len(seen) >= 2 and regex.fullmatch(r'\p{Script=Han}', token)
                and len(text) >= 2 and cedict.glosses(text[-2:])):
            value = -0.4
        for phrase, pulse in PULSES.items():
            spans_tokens = len(phrase.encode('utf-8')) > len(raw)
            whole_marker = phrase in {'年夜', '不克不及'}
            if text.endswith(phrase) and (spans_tokens or whole_marker):
                value = pulse
    return (doc, pos + 1, token, joined[-32:], seen), value

programs.haiku:
"""Document-start only: predict the mean activation of the first token of each document."""
READS = ()

def step(carry, prefix, upstream):
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    return None, (-0.24 if new_doc else 0.0)

programs.sol:
"""Approximate an orthographic i/y-vowel continuation feature.

The largest rules concern Vietnamese ie/ye (including split circumflex-e),
marks following i-like letters, and Greek/Thai vowel combinations. Tone and
syllable ending set the Vietnamese amplitude. Unrecognized text gets zero;
this deliberately omits many small, token-specific responses. A few separate
rules cover repeated middle dots and document-initial fragments/comments,
and the second digit of an initial 12. Spanish function words in the recent
text raise the estimate for split i-é. This is only a partial predictor.
"""
import re
import unicodedata as ud
from functools import lru_cache

READS = ()


@lru_cache(maxsize=16384)
def spelling(s):
    decomposed = ud.normalize('NFD', s.lower())
    plain = ''.join(c for c in decomposed if not ud.combining(c))
    return plain, decomposed


def response(previous, token, tail, initial):
    plain, marks = spelling(token)
    before, _ = spelling(previous)
    attached = bool(token) and not token[0].isspace()
    if token and set(token) == {'·'} and len(token) >= 2:
        return -1.4 if previous.endswith('·') else 0.0
    if token == '//\n' and (initial or previous == '<|endoftext|>'):
        return 2.4
    if initial and re.fullmatch(r'(?:ch)?ie[nt]?', plain):
        return -2.1

    # Vowel fragments following isolated aspirated/palatal digraphs.
    if attached and re.fullmatch(r'ie[nvt]?', plain):
        if before.strip() in ('ch', 'th', 'ph', 'bh', 'sch'):
            return -1.2
    if token == 'eh' and before.endswith('y'):
        return 1.7

    # The initial numeral 12 is an unusually strong boundary response.
    if token == '2' and (tail == '1' or tail.endswith('<|endoftext|>1')):
        return -5.5

    # Marks after a palatal vowel/glide, especially Arabic ya + shadda.
    if token and ud.category(token[0]).startswith('M'):
        if before.endswith(('ي', 'ى')):
            return 6.0 if token == 'ّ' else 3.0
        if before.endswith(('i', 'y', 'ι', 'и', 'і', 'י')):
            return 2.3
        if previous.endswith('و') and token == 'ّ':
            return 1.0

    if plain == 'υ' and spelling(tail)[0].endswith('ιε'):
        return -5.2
    if token == 'อง' and tail.endswith(('ื่', 'ื')):
        return -3.7
    if token == '่' and previous.endswith('ิ'):
        return 2.1
    if token == '่' and previous.endswith('ุ'):
        return 0.5
    if token == 'ง' and tail.endswith('ิ่'):
        return -2.2

    if attached and before.endswith(('i', 'y')):
        if plain in ('yy', 'yah', 'ah', 'ye'):
            return 2.0 if plain == 'yy' else 1.0
    if attached and re.fullmatch(r'[iy]é', token.lower()):
        return 1.7

    # Vietnamese iê/yê nuclei: tone plus syllable coda, not word identity.
    word = token.strip().lower()
    nucleus = re.search(r'[iy][êềếệểễ]', word)
    split = (attached and before.endswith(('i', 'y'))
             and bool(word) and word[0] in 'êềếệểễ')
    if nucleus or split:
        end = spelling(word[nucleus.start()+2:] if nucleus else word[1:])[0]
        if end in ('', 'u', 'ng', 'n', 'm', 't', 'c', 'p'):
            if split:
                return -2.6
            tone = next((name for mark, name in (
                ('\u0300', 'grave'), ('\u0301', 'acute'),
                ('\u0323', 'dot'), ('\u0309', 'hook'),
                ('\u0303', 'tilde')) if mark in marks), 'plain')
            if end == 'u':
                return {'grave': -4.2, 'acute': -0.9, 'dot': -1.3,
                        'hook': -1.5, 'plain': -1.1, 'tilde': 0.0}[tone]
            if end == 'ng':
                return {'acute': -3.3, 'plain': -2.1}.get(tone, 0.0)
            if tone == 'plain' and word.startswith(('ngh', 'nh')):
                return 0.0
            return {'grave': -0.8, 'acute': -1.2, 'dot': -0.3,
                    'hook': -0.3, 'plain': -0.8, 'tilde': -0.5}[tone]

    if attached and before.endswith(('i', 'y', 'ι')) and plain.startswith('e'):
        if '\u0308' in marks:
            return 4.5
        if '\u0301' in marks:
            spanish = re.search(r'\b(?:los|las|del|una|por|para|y)\b', tail.lower())
            return 2.8 if spanish else 0.45
        if re.fullmatch(r'e(?:h|v|k|g|th)?', plain):
            return 0.2
    if attached and plain.startswith(('u', 'w')) and before.endswith('ie'):
        return -0.4
    if token == 'ng' and re.search(r'[iy][êềếệểễ]$', tail.lower()):
        return -4.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    previous, tail = ('', '') if initial else carry[1:]
    token = prefix.token_strings[-1]
    value = response(previous, token, tail, initial)
    return (doc, token, (tail + token)[-256:]), float(value)

"""Detect criticism/appraisal vocabulary and opinion-preposition constructions.

Negative responses mark criticism (including related European spellings),
reviews, crisis, ethical/theoretical words, and 'agree with'-like phrases.
Spelling rules distinguish critter/criterion, early tri-/tru- fragments,
and weak t-boundary continuations. These are lexical approximations, not
a complete account of the component. The 100-character tail resets per document.
"""
import re
import unicodedata

READS = ()


def cue(tail, token):
    s = token.strip().lower()
    previous = re.search(r'[^\W\d_]+\s*$', tail.lower())
    previous = previous.group().strip() if previous else ''
    if s == 'with':
        if re.fullmatch(r'(?:dis)?agree(?:s|d)?', previous):
            return -6.0
        if previous in ('pleased', 'satisfied', 'happy', 'delighted',
                        'disgusted', 'frustrated', 'dissatisfaction'):
            return -3.6
        if previous in ('agreement', 'disagreement', 'disagreements',
                        'satisfaction', 'discontent', 'impressed'):
            return -1.9
        if previous in ('problem', 'problems', 'trouble', 'content',
                        'clash', 'love', 'interview', 'obsessed'):
            return -0.7
    if s == 'of':
        if previous == 'critical':
            return -6.5
        if previous == 'proud':
            return -4.0
        if previous in ('criticism', 'criticisms', 'critic', 'critique'):
            return -3.2
        if previous in ('sick', 'ashamed', 'disapproved'):
            return -1.6
    text = tail + token
    if text.endswith(('批评', '批評', '비판', '书评', '書評')):
        return -7.8 if len(token) == 1 else -4.0
    m = re.search(r'[^\W\d_]+$', text.lower())
    if not m or not token or not token[-1].isalpha():
        return 0.0
    word = ''.join(c for c in unicodedata.normalize('NFD', m.group())
                   if unicodedata.category(c) != 'Mn')
    split = bool(tail and tail[-1].isalpha() and token[0].isalpha())
    if re.fullmatch(r'critters?', word):
        return 4.3
    if re.fullmatch(r'crit[eè]r.*', word):
        return 1.3 if split else 0.0
    if word == 'krit':
        return -4.6
    if word.startswith('kritik'):
        return -10.8 if s == 'ik' else -4.5
    if word == 'крит':
        return -3.0
    if re.fullmatch(r'(?:un)?crit', word):
        return -0.9
    if re.fullmatch(r'(?:un|trans)?critical(?:ly)?', word):
        return -3.8 if split else -1.6
    if re.fullmatch(r'critics?', word):
        return -6.4 if split else -5.2
    if re.fullmatch(r'critic(?:is|iz).*', word):
        return -5.8 if split else -3.7
    if word.startswith('critiqu'):
        return -7.5 if word == 'critiqu' else -4.7
    if re.fullmatch(r'critic(?:a|as|o|os|he|i)', word):
        return -5.0 if split else -3.5
    if word in ('crisis', 'кризис'):
        return -4.3 if split else -3.3
    if word in ('crises', 'kryz', 'криз'):
        return -2.0
    if re.fullmatch(r'.*politik(?:a|en)?', word):
        return -4.8
    if re.fullmatch(r'satirical|s[ck]eptic(?:al|ism)', word):
        return -2.8 if split else -0.8
    if word == 'treatise':
        return -2.4 if split else -0.7
    if re.fullmatch(r'review(?:s|ed|er|ers|ing)?', word):
        if re.search(r'\b(?:positive|peer|book|film)[ -]*$', tail, re.I):
            return -2.8
        return -1.1 if word.endswith('s') else -0.65
    if re.fullmatch(r'theoretical(?:ly)?', word):
        return -1.8
    if re.fullmatch(r'ethic(?:al|ally|s)?', word):
        return -0.9
    if re.fullmatch(r'etic(?:a|o|as|os)', word):
        return -2.6
    if word == 'politically':
        return -0.6
    # At a word-internal t boundary, i+c/k/q/s spellings are negative;
    # continuations with doubled consonants or er+n/m are positive.
    if split and previous.endswith('t'):
        if re.match(r'i(?:[ckq]|s(?!s))', s):
            return -0.4
        if re.match(r'ell|er[nm]|[ui]ss', s):
            return 0.7
    if (split and len(previous) <= 4 and len(word) <= 7
            and word.isascii() and re.match(r'tri[stl]|trus', word)):
        return 1.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (tail + token)[-100:]), cue(tail, token)

"""Approximate a spelling detector for -ov/-ow and Cyrillic -ов endings.

Short vowel/adjective endings give the strongest positive values, even
when the spelling is split between tokens. Bare Cyrillic -ов also depends
on the stem's final letter and capitalization. Longer words containing
the same letters are generally weaker. This is a spelling heuristic,
not a full morphological parser. Small extra rules cover .gov, the
initial metadata label Title:, and runs of middle dots.
"""
import re
import unicodedata

READS = ()

LATIN_ENDINGS = set('a o i u y'.split()) | {
    'ie', 'ego', 'ej', 'ych', 'ym', 'ymi', 'ou',
}
CYRILLIC_ENDINGS = {
    'а', 'о', 'е', 'у', 'и', 'ы', 'я', 'ая', 'ое', 'ые', 'ый', 'ой',
    'ых', 'ым', 'ыми', 'ого', 'ому', 'ом', 'ую', 'ий', 'их', 'им', 'ей',
}
ACCENTED = set('áéíóúýěůÁÉÍÓÚÝĚŮ')


def response(tail, token, at_title=False):
    s = token.lower()
    if at_title and token == ':':
        return 7.2
    if s and set(s) == {'·'} and len(s) > 1:
        return -1.0
    # The token must continue the same word for cross-token spelling.
    if s and s[0].isalpha():
        old = ''.join(c for c in tail.lower()
                      if not unicodedata.combining(c))
        if old.endswith(('ov', 'ow', 'ов', 'ев')):
            if s == 'і':
                return 6.7
            if s == 'á':
                return 9.2
            if s in {'é', 'ě', 'ý', 'ú', 'í', 'ých', 'ými', 'ého', 'ým', 'ém', 'ému'}:
                return 5.3
            if s in CYRILLIC_ENDINGS:
                return 3.5
            if s in set('a o i u y'.split()):
                return 4.7
            if s in LATIN_ENDINGS:
                return 2.2
            if s == 'e':
                return 1.6
            return 0.1 if len(s) > 4 else 0.3
        if old.endswith(('o', 'о', 'ů')) and s.startswith(('v', 'w', 'в')):
            end = s[1:]
            if not end:
                if token == 'В':
                    return 0.8
                return 5.3 if s == 'в' else 3.4
            if end in LATIN_ENDINGS or end in CYRILLIC_ENDINGS:
                return 6.1
            if len(s) <= 3 and any(c in ACCENTED for c in token):
                return 6.1
            return 0.2 if len(s) > 3 else 0.9
    # Also recognize a complete fragment within the current token.
    m = re.search('ov|ow|ов', s)
    if not m:
        return 0.0
    pre, end = s[:m.start()], s[m.end():]
    cyrillic = m.group() == 'ов'
    if not pre:
        if not end:
            if cyrillic:
                strong_stem = bool(tail) and tail.lower()[-1:] in 'дгзпхб'
                capital = tail[:1].isupper()
                return ((3.7 if capital else 2.4)
                        if strong_stem else (1.9 if capital
                                        else -0.1))
            return 2.1 if m.group() == 'ov' else 1.2
        if cyrillic:
            if end in CYRILLIC_ENDINGS:
                return 3.8 if end == 'а' else 6.1
            return 1.2
        if end in LATIN_ENDINGS or any(c in ACCENTED for c in end):
            return 3.8
        if end == 'e':
            return 2.0
        if end in {'s', 'ic', 'an', 'al'}:
            return 1.4
        return 0.1
    if s == '.gov':
        return 4.6
    if len(pre.strip()) <= 2:
        if not end:
            if cyrillic:
                return 1.4 if pre[0].isspace() else 0.2
            if m.group() == 'ov':
                return 0.6
            if pre.strip() in {'p', 'g', 's'}:
                return 1.3
        if cyrillic and end in CYRILLIC_ENDINGS:
            return 0.5
        if (end in {'a', 'o', 'y'} and pre.strip()[-1:].isalpha()
                and pre.strip()[-1:] not in 'aeiouy'):
            return 1.3
    if s == ' over':
        return 0.2
    return 0.0


def word_tail(old, token):
    # Keep only the unfinished word; NULs sometimes separate encoded letters.
    text = old + token.replace('\x00', '')
    n = len(text)
    while n and (text[n-1].isalpha() or unicodedata.combining(text[n-1])):
        n -= 1
    return text[n:][-32:]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, count = '', '', 0
    else:
        _, tail, previous, count = carry
    token = prefix.token_strings[-1]
    value = response(tail, token, previous == 'Title' and count <= 2)
    return (doc, word_tail(tail, token), token, count + 1), value

"""A word-level 'if' detector, strongest for conditions in ordinary prose.

Source-code ifs are weaker. Comparisons ('as if'), necessary conditions
('only if'), and indirect questions ('check if') have separate responses.
For ambiguous si/se, nearby word frequencies identify the prose language.
This is an approximation: it omits most small, non-conditional activations.
"""
import re
from wordfreq import zipf_frequency
from wordnet import base_forms

READS = ()


def language(text):
    """Which language makes the recent words most familiar?"""
    words = [w for w in re.findall(r'[^\W\d_]+', text.lower())[-40:]
             if len(w) > 1]
    if not words:
        return None
    scores = {lang: sum(zipf_frequency(w, lang) for w in words) / len(words)
              for lang in ('en', 'it', 'pt', 'es', 'fr', 'de', 'ro', 'cs', 'sv')}
    best = max(scores, key=scores.get)
    return best if scores[best] > 2 else None


def response(token, before):
    word = token.strip().lstrip('“”"\'—–(')
    low = word.lower()
    attached = (token == word and before and before[-1].isalpha()
                and not before.endswith(('\\n', '\\t', '\\r')))
    if low == 'if':
        if not before:
            return 0.35
        # Capital If also marks word boundaries in camelCase identifiers.
        if attached and word.islower():
            return -0.65
        if word.isupper():
            return 0.55 if token[:1].isspace() else 0.10
        if word[:1].isupper():
            return 1.50 if token[:1].isspace() else 1.30
        prev = re.findall(r'[\w]+|[^\w\s]', before.lower())
        prev = prev[-1] if prev else ''
        if prev == 'as':
            return -0.16
        if prev == 'only':
            return 0.59
        if re.search(r'\b(depending|depends) on\s*$', before.lower()):
            return 0.03
        forms = set(base_forms(prev)) | {prev}
        if forms & {'check', 'see', 'test', 'determine', 'sure', 'clear',
                    'tell', 'examine', 'detect', 'verify', 'investigate',
                    'doubt', 'regardless'}:
            return 0.02
        if prev == 'out' and re.search(r'\b(find|figure) out\s*$', before):
            return 0.02
        if forms & {'know', 'wonder', 'ask', 'decide', 'unsure'}:
            return 0.28
        if prev == 'even':
            return 1.23
        if prev == 'else':
            return 0.87
        if '\t' in token:
            return 0.75
        line = re.split(r'\n|\\n', before)[-1]
        if not line.replace('\\t', '').strip() and '\\' in before[-4:]:
            return 0.60
        if not line.strip() or re.fullmatch(r'[\s\d+\-]*', line):
            return 0.69 if token[:1].isspace() else 0.80
        if prev in {',', 'that', 'but', 'so', 'because', 'again'}:
            return 1.63
        if prev == 'and':
            return 1.40
        code_syntax = (r'[{};=]|\\[nt]|'
                       r'\b(print|return|self|const|let|def|var|public|function)\b')
        if re.search(code_syntax, before[-160:]):
            return 0.85
        return 1.22 if prev != '(' else 1.78
    if low in {'si', 'se'}:
        if attached or word.isupper():
            return -0.03
        lang = language(before)
        capital = word[:1].isupper()
        if low == 'si':
            return {'es': 2.05 + 0.25 * capital,
                    'fr': 1.52 + 0.35 * capital}.get(lang, 0.08)
        return {'it': 2.35 + 0.45 * capital,
                'pt': 1.03 + 1.45 * capital}.get(lang, -0.13)
    russian_if = (low in {'сли', 'ли'}
                  and re.search(r'(?<!\w)если$', (before + word).lower()))
    if low == 'если' or russian_if:
        return 2.25 if word[:1].isupper() or before.endswith('Е') else 1.95
    if word.startswith('如果'):
        return 1.03 if word in {'如果', '如果你', '如果您'} else 0.30
    if word == '若':
        return 1.03 if token[:1].isspace() else 0.34
    if low == 'nếu':
        return 1.45
    if low == 'wenn':
        return 0.50
    if low == 'as' and not attached:
        return 0.20 if word[:1].isupper() else 0.04
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (doc, (before + token)[-600:]), float(value)

"""A local, approximate response to English definite noun phrases.

Immediately after 'the', score the token using dictionary classes and
singular/plural word frequencies; demonstratives get a weaker response.
Common entity classes tend to receive negative scores. Retain the latest
word's score for nearby possessive suffixes and auxiliary/copular verbs.
Individual noun amplitudes and longer context are deliberately omitted.
"""
import re
from functools import lru_cache
import wordnet
import inflect
from wordfreq import zipf_frequency
_ENGINE = inflect.engine()

@lru_cache(maxsize=40000)
def head_score(text):
    w = text.strip().lower()
    if not w.isascii() or not w.isalpha():
        return -0.30 if not w else -0.13
    cats = wordnet.categories(w)
    # A familiar plural is a coarse cue to countable entity words.
    plural = _ENGINE.plural_noun(w) or w
    plural_frequency = zipf_frequency(plural,'en')
    ratio = plural_frequency - zipf_frequency(w,'en')
    if plural_frequency <= 4.30:
        if ratio <= -1.20:
            return -0.42 if ratio <= -6.03 else -0.02
        return -0.13
    if wordnet.is_a(w,'institution'):
        return -0.60 if ratio <= -0.45 else -1.52
