    if wordnet.is_a(w,'geographical area'):
        return -1.21 if noun_classes <= 3 else -0.37
    if wordnet.is_a(w,'quality'):
        return 0.39 if ratio <= -0.80 else -0.16
    if ratio > 0.0:
        return -0.10
    if 'noun.cognition' in cats:
        return -0.28
    if wordnet.is_a(w,'physical entity'):
        return -0.39
    if 'noun.group' in cats:
