    clean = text.strip()
    lower = clean.lower()
    after_the = bool(re.search(r'(?:^|\W)the$', previous, re.I))
    after_demo = previous.lower() in DEMONSTRATIVES
    continuation = (not text[:1].isspace() and clean.isascii()
                    and clean.isalpha() and word and age < 5
                    and not (after_the or after_demo))
