    score = head_score(whole)
    value = -0.08 if first else 0.0
    if after_the:
        value += 0.98 * score
    elif after_demo:
        value += 0.17 * score
    elif age < 4:
        if lower in {"'s", '’s', "'"}:
            value += -0.71 + 1.21 * last_score
        elif lower in AUXILIARIES:
