import unicodedata

READS = ()


def unfinished(data):
    for i in range(len(data) - 1, max(-1, len(data) - 5), -1):
        byte = data[i]
        if byte < 128:
            return b''
        if byte >= 192:
            width = 2 if byte < 224 else 3 if byte < 240 else 4
            return data[i:] if len(data) - i < width else b''
    return b''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    pending = carry[1] if carry and carry[0] == doc else b''
    token = prefix.token_bytes[-1]
    first = not carry or carry[0] != doc
    if prefix.position > 0:
        first = first or prefix.token_bytes[-2] == b'<|endoftext|>'
    initial_cr = token == b'\r' and (
        first or (carry and carry[0] == doc and carry[2]))
    tail = unfinished(pending + token)
    continuation = bool(token) and all(128 <= b < 192 for b in token)
    value = 0.04 if continuation else -0.001
    if tail:
        lead = tail[0]
        width = 2 if lead < 224 else 3 if lead < 240 else 4
        missing = width - len(tail)
        # Zero-fill the unseen low bits to locate the character's region.
        char = (tail + b'\x80' * missing).decode('utf8', 'replace')[0]
        category = unicodedata.category(char)
        han = bool(regex.fullmatch(r'\p{Script=Han}', char))
        syllabic = bool(regex.fullmatch(
            r'\p{Script=Hangul}|\p{Script=Yi}', char))
        japanese = bool(regex.fullmatch(
            r'\p{Script=Hiragana}|\p{Script=Katakana}', char))
        greek = bool(regex.fullmatch(
            r'\p{Block=Greek_and_Coptic}|\p{Script=Greek}', char))
        space = token.startswith(b' ')
        if width == 2:
            if greek:
                value = 0.23
            elif category in ('Cc', 'Cn'):
                value = 0.05
            elif regex.fullmatch(r'\p{Script=Latin}', char):
                value = 0.74
            else:
                value = 0.54
        elif width == 4:
            value = (1.4 if continuation else 0.3 if space else 0.8)
            if missing > 1:
                value = 0.3
        elif missing > 1:
            if han:
                value = 0.06 if space else 0.85
            else:
                value = 0.55 if syllabic else 0.14
        elif continuation:
            value = 2.0 if greek else 0.85 if category == 'Co' else 1.4
            if syllabic:
                value = 1.57
        elif han:
            value = 0.16 if space else 0.87
        elif syllabic:
            value = 0.8
        elif japanese:
            value = 0.15
        elif category == 'Sm':
            value = 0.11 if space else 0.4
        elif category.startswith('N'):
            value = 0.36
        else:
            value = 0.25 if space else 0.6
    if initial_cr:
        value = 2.42
    elif first and not tail:
        if token.isspace() and b'\t' in token:
            value = 1.43 if token == b'\t' else 0.65
        elif token.isspace() and b'\n' in token:
            value = 0.39 if token == b'\n' else 0.28
        elif (b'\n' in token and len(token) <= 6
              and not any(chr(b).isalnum() for b in token)):
            value = 0.45
    return (doc, tail, bool(initial_cr)), value

