        elif old == 'Title' and s == ':' and pos == 1:
            value = 1.98
        elif s == '\x00':
            value = -0.047
        elif s == '</think>':
            value = 0.176
        elif s == '</tool_call>':
            value = -0.137
        elif s == '<|im_end|>':
            value = 0.06
        elif s == '.com':
            value = 0.10
        elif len(s) >= 2 and set(s) == {'·'}:
            value = 0.86
    return (doc, token, pos), value

programs.haiku:
"""Document-start detector for layer 1, MLP down_proj component 3408.

The component is silent inside a document and fires on the first token of each
document: the token right after a document break (<|endoftext|> and friends), or
the first token of a row. There the attention sees nothing before it, so the
strength is set by which token opens the document. Strengths, roughly as measured
on training text:

  articles (the, a, an)                         about 17 (13 with a leading space)
  code keywords (def, import, class, ...)       about 13
  pronouns and question words (I, it, what...)  about 12 (8 with a leading space)
  capitalised words                             about 10 (8 with a leading space)
  lowercase words                               about 8
  prepositions and conjunctions (in, of, and)   about 8 (6 with a leading space)
  everything else (punctuation, digits, ...)    about 6

A leading space means the document was cut mid-sentence, so the response is weaker.
Inside a document the component is ~0 (a weak response to a few repeated-token
runs is ignored here).
"""

READS = ()

ARTICLES = {"the", "a", "an"}
CODE_WORDS = {
    "def", "import", "from", "class", "int", "const", "function", "export",
    "return", "var", "let", "public", "static", "void", "package", "using",
}
PRONOUNS = {
    "this", "that", "these", "those", "i", "it", "he", "she", "we", "they", "you",
    "what", "which", "who", "how", "why", "when", "where", "there", "here", "my",
    "your", "our", "its", "his", "her", "their", "some",
}
PREPOSITIONS = {
    "in", "on", "for", "is", "if", "as", "at", "by", "with", "from", "and", "but",
    "so", "then", "of", "to",
}


def start_strength(token):
    """How strongly a document-opening token drives the component."""
    word = token.strip()
    lower = word.lower()
    spaced = token[:1] == " "
    if word in CODE_WORDS:
        return 13.0
    if lower in ARTICLES:
        return 13.0 if spaced else 17.0
    if lower in PRONOUNS:
        return 8.5 if spaced else 12.0
    if lower in PREPOSITIONS:
        return 6.0 if spaced else 8.5
    if word.isascii() and word.isalpha():
        if word[0].isupper():
            return 7.8 if spaced else 9.7
        return 7.7
    return 6.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids
    at_start = len(doc) == 1 or doc[-1] != doc[-2]
    if not at_start:
        return carry, 0.0
    return carry, start_strength(prefix.token_strings[-1])

programs.sol:
"""Detect HTTPS URL openings and a few smaller punctuation patterns.

The large response is the :// after https (including split ':' and '//').
The scheme and familiar web-host prefixes respond less strongly. Other small
responses mark LaTeX environment braces and initial four-column indentation;
continued middle-dot runs have a negative response. A leading :// gets an
intermediate response because its scheme is missing. These rules summarize
repeatable training patterns; weaker lexical effects are left at zero.
"""

READS = ()
WEB_HOST_PREFIXES = {'docs', 'doi', 'images', 'img'}


def is_https(token):
    # A scheme can share its token with an opening quote.
    return token.lstrip(" \t\"'") == 'https'


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, before_previous, after_opening = '', '', False
    else:
        _, previous, before_previous, after_opening = carry

    secure_opening = (
        token == '://' and is_https(previous)
        or token == '//' and previous.strip() == ':'
        and is_https(before_previous)
    )
    value = 0.0
    if secure_opening:
        value = 13.1
    elif token == '://':
        value = 5.7 if first else 0.3
    elif is_https(token):
        value = 0.25 if token.startswith(' ') else 0.95
    elif after_opening:
        if token.strip() == 'www':
            value = 7.3 if token == 'www' else 3.8
        elif token in WEB_HOST_PREFIXES:
            value = 3.5
    elif (token == '{' and previous in ('begin', 'end')
          and before_previous.endswith('\\')):
        value = 1.9 if previous == 'begin' else 1.6
    elif first and token and not token.strip(' '):
        # A following space-prefixed word can finish four-column indentation.
        width = len(token)
        if width > 1:
            value = 2.4 / (1.0 + width / 40.0) if width % 4 == 3 else 0.7
    elif (len(token) >= 2 and not token.strip('·')
          and previous and not previous.strip('·')):
        value = -1.56

    return (doc, token, previous, secure_opening), value

"""Approximate the component's large repeat-sensitive punctuation responses.

Keep a short normalized text tail. Repeated punctuation, delimiters, and
literal backslash-n/backslash-t escapes mostly give negative responses.
Token shape and punctuation family set their size; an added dot ending a
line is positive. Predict zero elsewhere, omitting the smaller word-specific
background activations. Reset the tail at document boundaries.
"""
import unicodedata
from functools import lru_cache
READS = ()

@lru_cache(maxsize=32768)
def normalized(text):
    text = unicodedata.normalize('NFKC', text)
    return ''.join('-' if unicodedata.category(c) == 'Pd' else
                   '"' if c in '“”„‟' else
                   "'" if c in '‘’‚‛' else c for c in text)

@lru_cache(maxsize=32768)
def symbolic(text):
    return bool(text) and len(text) <= 8 and all(
        not c.isalnum() and not c.isspace() and c != '�' for c in text)

def response(text, tail):
    t = text.strip()
    prev = tail.rstrip()
    if not t or not prev:
        return None
    for letter in 'nt':
        unit = '\\' + letter
        if t.startswith(unit) and prev.endswith(unit):
            return {'n': -1.43, 't': -0.80}.get(letter)
    if t == '\\' and prev.endswith(('\\n', '\\t', '\\r')):
        return -0.8
    if not symbolic(t):
        return None
    if t.startswith('\\"') and prev.endswith('\\"'):
        return -4.0
    gap = tail[len(prev):] + text[:len(text)-len(text.lstrip())]
    if '\n' in gap or '\r' in gap:
        # Identical operators on successive otherwise blank lines.
        if len(t) == 1 and text.endswith(('\n', '\r')) and prev[-1] == t:
            return -2.35 if t in '+<>=/' else None
        return None
    # Repeated multi-character marks, such as {} or escaped asterisks.
    if 2 <= len(t) <= 4 and len(set(t)) > 1 and prev.endswith(t):
        return -1.44 if '\\' in t else -0.77
    if t == '(-' and prev.endswith('-'):
        return -2.84
    c = t[0]
    if not prev.endswith(c):
        return None
    spaced = text[0].isspace()
    # The second spaced dot is strongly negative; later dots are weaker.
    if c == '.':
        if not spaced and text.endswith(('\n', '\r')):
            return 1.45
        if t == '.' and spaced:
            run = 0
            in_dots = False
            for ch in reversed(prev):
                if ch == '.':
                    if not in_dots: run += 1
                    in_dots = True
                elif ch.isspace(): in_dots = False
                else: break
            return -2.84 if run == 1 else -0.33
        return None
    # Quotes, code delimiters and other repeated marks have different sizes.
    if c == '"' or c == "'":
        return (-1.31 if len(t) == 1 else -2.55) if spaced else -0.47
    if c == '`':
        return -1.85 if spaced and len(t) == 1 else None
    if c == '_':
        return -3.48 if spaced and t == '_' else None
    if c in '()[]{}':
        return -1.35 if spaced and len(t) == 1 else None
    if c == '\\':
        return -2.19 if spaced else -0.77 if len(t) > 1 else None
    if len(t) > 2:
        return None
    if c in '|∣':
        return -1.99 if spaced else -4.65 if c == '∣' else -0.12
    if spaced:
        return -1.79
    if len(t) == 1 and text.endswith(('\n', '\r')) and c in '+<>=/':
        return -2.35
    return None

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    text = normalized(prefix.token_strings[-1])
    value = response(text, tail)
    if value is None:
        value = 0.0
    return (doc, (tail + text)[-128:]), value

programs.haiku:
r"""Layer 1 MLP down_proj, component 3410: a negative "repeated symbol" detector.

It goes negative when the current token repeats the token just before it and that token
is a symbol or an escape. This happens in dividers and escaped text: runs of escaped
quotes and newlines inside JSON strings holding code, backtick-separated code, and table
or rule lines such as " _ _ _" or " | |". Repeated words, digits and spaces do nothing.
A single symbol does nothing. Its size depends on the symbol.

Plain-terms rule, using only the current and previous token:
  - the same escape or backtick token again: escaped quote -4.5, "<" newline -3.5,
    space-backtick -2.2, escaped newline -1.7, escaped tab -1.0
  - the same spaced symbol again (" _", " |", " -", " =")         -> -2.5
  - the same bare symbol again                                     -> -1.0
  - the same full stop again (". ." and " .")                      -> -0.8
  - the same symbol with different spacing (" .", ".")             -> -1.5
  - an escape or backtick right after another, not a repeat        -> -0.5
  - an escaped newline right after a lone "n" (a split "\n\n")     -> -1.2
  - otherwise                                                      -> 0
"""

READS = ()

ESCAPE_REPEAT = {'\\"': -4.5, "<\n": -3.5, " `": -2.2, "\\n": -1.7, "\\t": -1.0}


def core(s):
    return s.strip(" \xa0")


def is_ascii_symbol(s):
    """Only ASCII punctuation or symbols (a trailing newline may ride along); no letters or digits."""
    c = core(s)
    return any(not ch.isspace() for ch in c) and all(ch.isascii() and not ch.isalnum() for ch in c)


def is_markup(s):
    return "\\" in s or s.strip() == "`" or s == "<\n"


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    cur, prev = toks[-1], toks[-2]
    if cur == prev and (is_ascii_symbol(cur) or is_markup(cur)):
        if cur in ESCAPE_REPEAT:
            return None, ESCAPE_REPEAT[cur]
        if "." in cur:
            return None, -0.8
        if cur.startswith(" "):
            return None, -2.5
        return None, -1.0
    if core(cur) == core(prev) and is_ascii_symbol(cur) and "." not in cur:
        return None, -1.5
    if is_markup(cur) and is_markup(prev):
        return None, -0.5
    if prev == "n" and cur == "\\n":
        return None, -1.2
    return None, 0.0

programs.sol:
"""A conservative spelling rule for short v/w fragments.

Av/aw continuations use negative d/n/b and earlier-vowel spelling rules.
A vowel immediately before another vowel plus v/w is positive. Bare
v/w after ee or au is also positive. These are approximate ASCII/Cyrillic spelling
responses, not meanings. Other tokens receive zero. State is a word tail,
reset at document boundaries; predictions are shrunk for uncertainty.
"""
import re
import unicodedata
from anyascii import anyascii

READS = ()


def western(s):
    return all(c.isascii() or 'CYRILLIC' in unicodedata.name(c, '') for c in s)


def response(token, word):
    if not western(token):
        return 0.0
    if token[:1].isupper() and not token.isupper():
        return 0.0
    s = anyascii(token).lower()
    p = anyascii(word).lower() if western(word) else ''
    last = p[-1:]
    m = re.fullmatch(r'([aeou])[vw]([a-z]{0,3})', s)
    if m:
        vowel, tail = m.groups()
        allowed = (not tail
                   or (vowel == 'a' and re.fullmatch(r'[aiy]?[nrm]?|e', tail))
                   or (vowel == 'e' and tail in ('s', 'an'))
                   or (vowel == 'o' and p.endswith('o')
                       and tail in ('e', 'es', 'y')))
        if not allowed:
            return 0.0
        if last and last in 'aeou':
            return 2.5 + 0.5 * (last == 'o') + 0.5 * (tail == 'e')
        if last in ('y', 'j') and vowel == 'e':
            return 1.0
        if vowel == 'a':
            prior_vowel = bool(re.search('[aeiou]', p[-6:-1])) and last != 't'
            strength = (2.5 * (last == 'd') + 1.5 * (last == 'b')
                        + (last == 'n') + 0.5 * prior_vowel
                        + prior_vowel * (last in ('d', 'n'))
                        + p.endswith('an'))
            return -strength * (0.25 if tail == 'e' else 1.0)
    m = re.fullmatch(r'[vw]([a-z]{0,3})', s)
    if m and p.endswith(('ee', 'au')):
        return 4.0 * 0.7 ** len(m.group(1))
    if re.fullmatch(r' ?[a-z]*oov(?:e|es|y|ing)?', s):
        return 3.0
    if re.fullmatch(r'\s*[dn]a[vw]', s):
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    prediction = 0.7 * response(token, word)
    word = re.split(r'[\W\d_]+', word + token)[-1][-24:]
    return (doc, word), float(prediction)

"""An approximate detector of document subdivisions and internal references.

Dotted outline numbers, label punctuation, and heading markup are positive.
Nested TeX section commands get especially large values. Phrases like 'this
section' and 'see above' also respond. Otherwise predict zero, apart from a
small negative value for lowercase 'results'. Keep only 700 recent bytes,
resetting this buffer when the document changes.
"""
import re

READS = ()
NUMBER = re.compile(r'(\d+(?:[.．]\d+)*[.．]?)$')
LABEL_MARGIN = re.compile(r'[\s#*>_\-•(（]*')
SECTION = re.compile(
    r'(?i)(?:\b(?:sections?|subsections?|chapters?|parts?|articles?)|§)\s*$'
)
HAN_NUMERALS = '一二三四五六七八九十'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent = b''
    else:
        _, recent = carry
    before = recent.decode('utf-8', errors='ignore')
    before = before.replace('\\r\\n', '\n').replace('\\n', '\n')
    token = prefix.token_bytes[-1]
    text = token.decode('utf-8', errors='replace')
    word = text.strip()
    line = before.rsplit('\n', 1)[-1]
    value = 0.0

    # Numeric labels: distinguish a line's outline from ordinary decimals.
    if text.isdecimal() or word in ('.', '.\\', '．', '.-', ')', '）', '、'):
        match = NUMBER.search(before.rstrip())
        number = match[0] if match else ''
        parts = re.findall(r'\d+', number)
        lead = before.rstrip()[:-len(number)] if number else before
        margin = lead.rsplit('\n', 1)[-1]
        at_margin = bool(match and LABEL_MARGIN.fullmatch(margin))
        section_ref = bool(match and SECTION.search(lead))
        dots = number.count('.') + number.count('．')
        small = bool(parts and int(parts[0]) < 100)
        if text.isdecimal() and number.endswith(('.', '．')):
            # Low subdivision numbers are more characteristic of an outline;
            # zero and long decimal fractions usually are not section labels.
            subdivision = int(text)
            if subdivision:
                if at_margin and small:
                    if '#' in margin:
                        value = 2.4 if subdivision <= 3 else 0.8
                    elif int(parts[0]) < 10:
                        value = 0.85 if subdivision <= 3 else 0.3
                    else:
                        value = 0.2
                elif section_ref:
                    value = (
                        1.8 if subdivision <= 3 and int(parts[0]) < 10 else 0.4
                    )
        elif text.isdecimal():
            pass
        elif word.startswith(('.', '．')) and at_margin and small:
            value = (2.0 if '#' in margin else 1.0) if dots else (
                1.2 if '#' in margin else 0.1 if int(parts[0]) == 1 else 0.3
            )
        elif word in (')', '）', '、') and at_margin and small:
            value = 0.25
        else:
            label = re.search(r'([A-Za-z一二三四五六七八九十]+)$', before)
            if label:
                label = label[0]
                margin = before[:-len(label)].rsplit('\n', 1)[-1]
                if LABEL_MARGIN.fullmatch(margin):
                    if all(c in HAN_NUMERALS for c in label):
                        value = 1.8 if word == '、' else 1.15
                    elif re.fullmatch('[IVXLCDM]+', label):
                        value = (
                            (1.25 if len(label) > 1 else 0.55)
                            if word.startswith('.') else 0.4
                        )
                    elif re.fullmatch('[ivxlcdm]+', label):
                        value = 0.5 if word.startswith('.') else 0.35
                    elif len(label) == 1:
                        value = 0.4 if word.startswith('.') else 0.2

    elif re.fullmatch(r'(?:sub)*sections?', word.lower()):
        if re.search(r'\\(?:sub)*$', before):
            extra = len(re.search(r'(?:sub)*$', before)[0]) // 3
            depth = word.lower().count('sub') + extra
            value = 2.9 if depth == 0 else 3.8 if depth == 1 else 6.3
        elif re.search(r'(?i)\b(this|next|following|previous|present)\s*$', before):
            value = 1.2 if word.startswith('sub') else 0.85
        elif word.startswith('sub'):
            value = 0.5
    elif word in ('above', 'below'):
        if re.search(r'(?i)\b(see|shown|mentioned|described|discussed|given|listed|'
                     r'detailed|noted|presented|specified|indicated|summarized)\s*$',
                     before):
            value = 1.0 if word == 'above' else 0.8
    elif word == '{' and re.search(r'\\(?:sub)*section$', before):
        value = 2.0
    elif word.lower() == 'results':
        if word[0].isupper():
            value = 0.8 if not line.strip() else 0.4
        else:
            value = -0.09
    elif word == '==' and not line.strip():
        value = 3.0
    elif word in ('The', 'THE') and re.fullmatch(r'\s*#{1,6}\s*', line):
        value = 1.1
    elif word == ':' and re.match(r'\s*#{1,6}\s+', line) and len(line) < 70:
        value = 0.6
    elif len(word) > 1 and re.fullmatch('[IVXLCDM]+', word):
        if LABEL_MARGIN.fullmatch(line):
            value = 0.4
    elif word and set(word) == {'#'} and len(word) <= 6:
        if LABEL_MARGIN.fullmatch(line):
            value = 0.36 if len(word) == 2 else 0.14 if len(word) > 2 else 0.0

    return (doc, (recent + token)[-700:]), float(value)

programs.haiku:
"""Section and list numbering detector.

The component fires on the punctuation that closes a numbering label at the start of a line:
'3.3.' (strongest), roman numerals 'II.', letters 'B.', plain numbers '2.' (weaker), and
CJK numerals '二、'. It also fires on the digit that starts the next sub-number after
'3.3. ' ('3.3. [[2]]'). Everywhere else it predicts 0. Mid-sentence numbers and ordinary
words are not predicted; they carry no consistent signal."""
import re
READS = ()
PFX = r"^[ \t]*(?:[#*\-]+[ \t]*)*(?:(?:[Ss][Ee][Cc][Tt][Ii][Oo][Nn]|§)[ \t]*)?"
LABEL = re.compile(PFX + r"(\d+(?:\.\d+)*|[IVXLCivx]+|[A-Z]|[一二三四五六七八九十]+)$")
SUB_THEN_DIGIT = re.compile(PFX + r"\d+(?:\.\d+)*\.[ \t]*$")
PUNCT = {".": None, "、": 1.0, "．": 0.7, ")": 0.25}
KIND_WEIGHT = {"sub": 1.5, "roman": 1.1, "letter": 0.45, "arabic": 0.3, "cjk": 1.0}

def kind(label):
    if "." in label:
        return "sub"
    if label.isdigit():
        return "arabic"
    if re.fullmatch(r"[IVXLCivx]+", label):
        return "roman"
    if re.fullmatch(r"[A-Z]", label):
        return "letter"
    return "cjk"

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    line = prefix.text_prefixes[prefix.position].split("\n")[-1]
    before = line[: len(line) - len(tok)]
    s = tok.strip()
    if "\n" in tok:
        return carry, 0.0
    if s in PUNCT:
        m = LABEL.match(before)
        if m:
            w = PUNCT[s] if PUNCT[s] is not None else KIND_WEIGHT[kind(m.group(1))]
            return carry, w
        return carry, 0.0
    if re.fullmatch(r"\d", s) and SUB_THEN_DIGIT.match(before):
        return carry, 0.6
    return carry, 0.0

programs.sol:
"""A lexical approximation of an ownership-versus-attributes signal.

Plural properties, programming props, powers, and selected foreign expressions
for properties/performance are negative. Possessors and real-estate modifiers
favor the positive ownership reading of singular property. A following 'of'
echoes the attribute reading. Repeated middle-dot leaders have a separate
negative response. Other tokens are approximated as zero.

A short byte tail recognizes split words and resets at document boundaries.
The Cyrillic prop- fragment is an orthographic rule, not a semantic one.
"""
import re

READS = ()
POSSESSORS = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
OWNERSHIP = {
    'private', 'personal', 'intellectual', 'real', 'family', 'public',
    'commercial', 'residential', 'local', 'taxable',
}
ABSTRACT = {
    'commutative', 'associative', 'distributive', 'additive', 'multiplicative',
    'additivity', 'homogeneity', 'transitive', 'reflexive', 'symmetric',
    'unique', 'universal', 'fundamental', 'important', 'following', 'basic',
    'intuitive', 'major', 'mechanical', 'this', 'that', 'what',
}
SCIENCE = re.compile(
    r'\b(theorem|equation|vector|matrix|hydrogen|chemical|scalar|contour|'
    r'gradient|commutative|distributive|crosslinking)\b', re.I)
ESTATE = re.compile(
    r'\b(lease\w*|foreclos\w*|lenders?|church|REO|bought|real estate|'
    r'property managers?)\b', re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = b'', ''
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    word = token.strip().lower()
    old = tail.decode('utf-8', 'ignore')
    tail = (tail + raw)[-240:]
    text = tail.decode('utf-8', 'ignore')
    value = 0.0

    if word and set(word) == {'·'} and len(word) >= 2:
        value = -1.9
    # Chinese: nature/quality, performance, attributes, and ownership rights.
    elif text.endswith('性質') and not old.endswith('性質'):
        value = -12.0 if word == '質' else -4.0
    elif word in {'性质', '性能', '属性', '品质'}:
        value = {'性质': -4.0, '性能': -2.6, '属性': -1.1, '品质': -1.7}[word]
    elif word in {'产权', '知识产权'}:
        value = 1.2
    # Korean: performance, attribute, inclination.
    elif old.endswith('성') and text.endswith('성능'):
        value = -4.0
    elif text.endswith(('속성', '성향')) and not old.endswith(('속성', '성향')):
        value = -2.8
    # French property, German properties, Cyrillic prop-, Spanish properties.
    elif old.lower().endswith('propri') and word == 'ét':
        value = -6.0
    elif old.lower().endswith('propriét') and word == 'és':
        value = -3.5
