    value -= 0.32 * min(paired, 1)
    if token == c and c in ')]':
        style = opening[1] if opening is not None else 'unmatched'
        if style == 'space':
            value += 0.20
        elif style == 'word':
            value -= 0.30
        elif style == 'unmatched':
            value -= 0.85 if c == ')' else 0.10
        else:
            value -= 0.15
    elif opening is None:
        value -= 0.20
    if token.startswith(' '):
        value += -0.15 if c == '>' else 0.20
    suffix = token[i + 1:]
    if '.' in suffix:
        value -= 0.62
    elif ';' in suffix:
        value -= 0.20 if c == '}' else 0.50
    elif ':' in suffix:
        value -= 0.15 if c == '}' else 0.50
    elif ',' in suffix:
        value += 0.12 if c == '}' else -0.32 if c in ')]' else 0
    elif any(ch in suffix for ch in '=+-*/^$'):
