"""Closing-bracket detector for layers.1.mlp.down_proj:3419.

What it does: this component writes a "a bracketed group just closed" signal. It is
active on a closing bracket (')', ']', '}', the full-width ')' and the CJK corner
and angle brackets) when that bracket closes a group opened earlier in the same
document. Its size depends on:
- how many tokens the group spans: a short "(x)" gives little; the activation
  rises over the first 3 to 5 tokens and then levels off (about 1.2 for ')');
- which bracket it is: ')' and ']' most, '}' less, CJK brackets about as ')';
- whether the closing token is bare (')' alone) rather than fused with what
  follows (')\\n', ').', '),', ');'), which is weaker (about 0.7 of it).
A closer whose opener is not in view gets a small constant. Empty pairs "()"
give nothing. Everything else is predicted as 0.

The program keeps a stack of open brackets through the document, so it needs only
the tokens seen so far, the same as the model.
"""

OPEN_TO_CLOSE = {"(": ")", "[": "]", "{": "}", "（": "）", "「": "」", "『": "』",
                 "《": "》", "【": "】", "〈": "〉", "〔": "〕"}
# how strongly each closing bracket drives the component
CLOSE_STRENGTH = {")": 1.3, "）": 1.3, "]": 1.1, "}": 0.65, "」": 0.8, "』": 0.8,
                  "》": 1.0, "】": 1.0, "〉": 0.8, "〕": 0.8}
STRAY = 0.5      # closer with no opener in view
SCALE = 2.5      # tokens to reach ~63% of the maximum
FUSED = 0.7      # a closer fused with following text is weaker

READS = ()


def step(carry, prefix, upstream):
    # carry: (stack, document id of last token); a stack entry is [closing char, token position]
    if carry is None:
        stack, last_doc = [], None
    else:
        stack, last_doc = carry
    t = prefix.position
    doc = prefix.document_ids[-1]
    if doc != last_doc:
        stack = []  # a new document: brackets from before do not count
    text = prefix.token_strings[-1]
    value = 0.0
    for ch in text:
        if ch in OPEN_TO_CLOSE:
            stack.append((OPEN_TO_CLOSE[ch], t))
        elif ch in CLOSE_STRENGTH:
            if stack and stack[-1][0] == ch:
                _, start = stack.pop()
                dist = t - start
                if value == 0.0 and dist > 0:
                    value = CLOSE_STRENGTH[ch] * (1 - 2.718281828 ** (-dist / SCALE))
                    if len(text) > 1:
                        value *= FUSED
            elif value == 0.0:
                value = STRAY
    return (stack, doc), value

