IDENTIFYING = re.compile(
    r'(?i)(?:phone|telephone|fax|mobile|cell|account|card|security|serial|'
    r'registration|reference|catalog|catalogue|accession|model|part|patent|'
    r'application|docket|case|file|contract|document|license|licence|'
    r'certificate|order|invoice|tracking|ticket|flight|channel|room|atomic|'
    r'code|control|company|seq|'
    r'juror|customer|student|employee|identification|identifying|page)\W*$'
)
