    r'(?i)\b(?:pat\.?|patent|application|publication|docket|file|ecf|'
    r'catalog|catalogue|citation|registration|case|contract|accession|'
    r'memorandum|doc|acc\.?|ser\.?|statement|report|id)\W*$'
)

def field_kind(text):
    match = re.search(r'(\w+)[^\w]*$', text)
    word = match[1] if match else ''
