        return 'id_label'
    if (word.lower() in {'id', 'identifier', 'pmid', 'doi', 'isbn', 'issn'}
            or word.endswith(('_id', '_ID', 'Id', 'ID'))):
        return 'id'
    if word.lower() in {'username', 'password'}:
        return 'credential'
    if word.lower() in {'name', 'key', 'code'}:
        return 'name'
    if word.lower() == 'for':
        return 'attribute'
    if word.lower() in {
        'email', 'mail', 'phone', 'telephone', 'tel', 'fax', 'title', 'nr', 'no'
    }:
