    return ''

NUMBER_WORDS = {'number', 'numbers', 'num', 'numeral', 'numerals',
                'numero', 'numéro', 'nummer', 'número'}


def response(s, recent):
    recent = recent.replace(r'\n', '\n').replace(r'\t', '\t')
