        if LEGAL.search(last):
            return -4.27
        if IDENTIFYING.search(last):
            return -3.18
        if bare.lower() in {'nos', 'nr'}:
            return -0.38
        return -0.1 if bare == 'no' else -0.58
    if bare.lower().lstrip('_') in NUMBER_WORDS:
        if not s[:1].isspace() and re.search(r'[a-zA-Z]$', recent):
