"""Negative on the token just before an identifier value is written. These are the words and
symbols that introduce an ID or a number: id="..." and for="..." attributes, getElementById('...')
and $('#...') selectors, record IDs (ID: 123, PMID: ...), serial, catalog and patent numbers
(No. 2, #9, number 5, №), and hex colours (fill="#c5..", color: #5CD).
The strongest values are on the opening quote, colon or '#' right after an id-like word."""
READS = ()

# words that name an identifier, and how strongly they fire on their own
ID_WORDS = {" id": 1.5, " ID": 1.5, "ID": 1.5, "_id": 1.5, " PMID": 2.0, " Id": 1.5,
            " Code": 1.5, " Email": 1.0, " ISBN": 1.0, " ISSN": 1.0, "号": 2.0, "编": 1.5}
# 'number', 'No' and '#' name an identifier mainly after a noun that is numbered
NUMBER_WORDS = {" number": 0.5, " numbers": 0.5, " Number": 0.5, " No": 1.0, "No": 1.0, " NO": 1.0,
                " #": 1.0, "#": 1.0, " Nr": 1.0, " №": 2.0, "号码": 2.0}
NAMED_BY = {"catalog", "registration", "serial", "patent", "application", "case", "docket", "model",
            "phone", "telephone", "card", "chassis", "code", "account", "atomic", "Doc", "Petition",
            "testcase", "Application", "Patent", "Model", "ECF", "Ser", "order", "invoice",
            "tracking", "reference", "policy", "license", "product", "item", "accession",
            "collection", "identification", "social", "ISBN", "CASE", "Doc.", "production"}
# a '#' that starts an id selector or hex colour fires whatever comes before it
HASH_OPENERS = {'="#': 5.0, ' "#': 4.0, "$('#": 4.0, ' $("#': 4.0, '$("#': 4.0, "('#": 4.0,
                '("#': 4.0, " '#": 4.0, "(#": 3.0, " (#": 3.0}
# a '#' right after a CSS colour property or border style starts a hex colour code
CSS_BEFORE_HEX = {":", " solid", " dashed", " dotted", " double"}
# punctuation that opens an identifier value right after such a label
OPENERS = {'="': 4.0, " '": 4.0, ' "': 1.5, "'": 2.5, '"': 1.5, ".": 1.5, ":": 1.5, "：": 1.5,
           "=": 2.0, "('": 3.0, '("': 1.5}
# attribute names whose value is an identifier
ID_ATTRS = {" id", " for", "-labelledby", "-describedby", "id", "for"}

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    if cur in HASH_OPENERS:
        return None, -HASH_OPENERS[cur]
    if cur in ("#", " #") and prev in CSS_BEFORE_HEX:
        return None, -7.0
    if cur in ID_WORDS:
        return None, -ID_WORDS[cur]
    if cur.endswith("ElementById"):
        return None, -3.0
    if cur in NUMBER_WORDS:
        if prev.strip() in NAMED_BY:
            return None, -4.0
        return None, -NUMBER_WORDS[cur] * 0.5
    if cur == '="' and prev in ID_ATTRS:
        return None, -6.0
    if cur in ("('", '("') and prev.endswith("ElementById"):
        return None, -6.0
    if cur in OPENERS:
        recent = toks[-3:-1]
        if any(t in ID_WORDS or t in NUMBER_WORDS or t in ("id", "Id") for t in recent):
            return None, -OPENERS[cur]
    return None, 0.0

