"""A document-start response, strongest for indentation and code line endings.

Most interior tokens contribute approximately zero. At the first visible token
of a document (including a cropped row), tabs, line breaks, Cyrillic, Kana,
Arabic, and hash-prefixed text receive larger positive responses. Explicit
template-open and escaped-tab markers also get positive responses. Paired middle dots
are a separate, position-independent punctuation response. These are coarse
surface-form rules, not a vocabulary lookup; individual words still vary.
"""
import math
import regex

READS = ()


def value(token, at_start):
    if token == "··":
        return 3.66
    if not at_start:
        return 0.0

    if token == "{{":  # Template opening delimiter.
        return 7.08
    if token == r"\t":  # A written-out tab escape.
        return 4.52

    if token.startswith("\t"):
        tabs = token.count("\t")
        if token.strip("\t") == "":
            return 20.14 / math.sqrt(tabs)
        if "\n" in token:
            return 9.73
        if token.isspace():
            return 8.0 / math.sqrt(1 + token.count(" "))
        return 2.7

    if "\n" in token:
        if token.rstrip("\r\n").endswith("."):
            return 0.14
        brackets = any(c in ")]}" for c in token)
        if brackets:
            if ";" in token:
                return 6.80
            return 4.0 if len(token) <= 3 else 4.67
        if "{" in token:
            return 6.3
        if ";" in token:
            return 4.4
        if token in ("\n", "\r\n"):
            return 3.49
        return 0.14 if "." in token else 1.76

    if regex.search(r"\p{Script=Cyrillic}", token):
        return 1.92 if token.islower() else 2.44
    if "#" in token:
        return 3.81 if len(token) >= 7 else 0.63
    if regex.search(r"[\p{Script=Hiragana}\p{Script=Katakana}]", token):
        return 2.22
    if regex.search(r"\p{Script=Arabic}", token):
        return 1.14
    if token.startswith("<|"):
        return -0.15
    return 0.10


def step(carry, prefix, upstream):
    at_start = (prefix.position == 0 or
                prefix.document_ids[-1] != prefix.document_ids[-2])
    return None, value(prefix.token_strings[-1], at_start)

"""A spelling-based approximation to an -ar/-ary/-aire ending detector.

Detached endings are strongest after t/d/n/r, weaker after other letters.
Several ways of splitting the same spelling across tokens are recognized.
Whole words get smaller responses, especially familiar English words;
necessity words and secretary titles are handled separately. The opposite
sign is used for 'jar'. A small offset applies at document starts.
This deliberately does not memorize the many individual-word differences.
"""
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16384)
def plain(text):
    if any(unicodedata.name(c, '').startswith(('CYRILLIC', 'GREEK'))
           for c in text):
        text = anyascii(text)
    return ''.join(c for c in unicodedata.normalize('NFKD', text.lower())
                   if not unicodedata.combining(c))


@lru_cache(maxsize=4096)
def familiar(word):
    return max(zipf_frequency(word, lang)
               for lang in ('en', 'fr', 'es', 'it', 'pt', 'de')) >= 3


def ending_strength(previous):
    p = plain(previous)
    c = p[-1:]
    if c and c in 'tdnr':
        cluster = len(p) > 1 and p[-2].isalpha() and p[-2] not in 'aeiou'
        return 0.74 if cluster else 1.0
    if c and c in 'aeiou':
        return 0.72
    if c and c in 'sz':
        return 0.67
    return 0.20


def activation(token, previous):
    s, p = plain(token), plain(previous)
    w = s.strip()
    if s == '.jar' or w == 'jar':
        return 1.01
    if s == ' of' and p.strip().startswith(('secretar', 'originator')):
        return -1.74
    if not w:
        return -0.003
    if 'r' in w and w.startswith(('necess', 'unnecess', 'neces')):
        return -1.33
    if w.startswith('secretar'):
        return -1.88
    if token in ('ь', 'Ь') and p.endswith('ar'):
        return -1.59
    if s[0].isalpha():
        strength = ending_strength(previous)
        if s.startswith('ar') and p.endswith('j'):
            return 1.01
        if s in ('ary', 'aries'):
            return -2.96 * strength
        if s in ('arian', 'arians', 'arius', 'arium'):
            return -5.31 * strength
        if s in ('aria', 'arias'):
            return -4.24 * strength
        if s in ('ario', 'arios', 'ari', 'aris'):
            return -5.44 * strength
        if s in ('aire', 'aires', 'taire', 'taires', 'ataire', 'ataires'):
            return -5.51 * strength
        if s in ('ar', 'ars'):
            return (-3.02 if 'ä' in token.lower() else -0.62) * strength
        if s in ('ire', 'ires'):
            if p.endswith('a'):
                return -6.06
            if p.endswith('o'):
                return -0.14
        if s == 'ery' and p.endswith(('n', 'a')):
            return -2.16
        if s in ('ious', 'ius', 'ia', 'io', 'i', 'y', 'ian', 'ians',
                 'ie', 'ies', 'ios', 'ium', 'ily', 'iness', 'ial', 'ially',
                 'iy', 'iya') and p.endswith('r'):
            return -1.59 if p.endswith('ar') else -0.59 if p.endswith('or') else -0.28
        if s in ('ri', 'ry', 'ria', 'rias', 'ris', 'ries') and p.endswith('a'):
            return -2.47
        if s == 'r' and p.endswith(('a', 'e', 'i', 'o', 'u')):
            return -0.72
        if len(s) <= 8:
            if s.endswith(('ary', 'aries', 'arian', 'arians', 'ariat',
                           'arily', 'arious')) and not familiar(s):
                return -1.12
            if s.endswith(('aire', 'aires', 'oire', 'oires')) and not familiar(s):
                return -2.32
    if w.endswith(('ary', 'aries', 'arian', 'arians', 'arium', 'arius',
                   'aria', 'ario', 'aire', 'aires', 'airy')):
        return -0.50 if zipf_frequency(w, 'en') < 4.2 else -0.12
