import unicodedata

READS = ()

# Things that a program defines, stores, or gives a name to.
PROGRAM_ENTITIES = frozenset({
    'function', 'class', 'method', 'variable', 'value', 'type', 'name',
    'object', 'instance', 'module', 'parameter', 'argument', 'property',
    'field', 'attribute', 'interface',
})


def opening_value(s):
    t = s.strip()
    if s == '\x00':
        return 23.8
    if s == '<|endoftext|>':
        return -9.3
    if s.startswith('<|'):
        return 0.48
    if not t:
        return -2.6 if len(s) > 1 and '\n' not in s else -2.0
    if t.isdigit():
        return -3.2 if t == '0' else -1.7
    # Comment and docstring openers.
    if t.startswith(('"""', "'''")):
        return -11.5 if '\n' in s else -8.0
    if t.startswith('/*'):
        return -8.8 if '\n' in s else -5.4
    if t.startswith('//') or t.startswith('#!'):
