    if low in {'the', 'a'}:
        return 0.2 if s.startswith(' ') and t.islower() else -2.2
    if low in {'this', 'that', 'these', 'those'}:
        return 0.5 if s.startswith(' ') and t.islower() else -0.9
    if low in {'my', 'your', 'our', 'his', 'her'}:
        return -2.2
    if low in PROGRAM_ENTITIES:
        return 10.0 if s.startswith(' ') and t.islower() else 3.5
    if low in {'in', 'on', 'at', 'of', 'by', 'from', 'with', 'for', 'to'}:
