READS = ()


def forms(words):
    """Approximate inflections for the semantic verb families below."""
    out = set()
    for w in words.split():
        out.update((w, w + 's', w + 'ed', w + 'ing'))
        if w.endswith(('ch', 'sh', 'ss', 'x', 'z')):
            out.add(w + 'es')
        if w.endswith('e'):
            out.update((w + 'd', w[:-1] + 'ing'))
        if w.endswith('y'):
            out.update((w[:-1] + 'ies', w[:-1] + 'ied'))
    return out


ENSURE = forms('ensure assure guarantee')
ENABLE = forms('allow enable permit')
PREVENT = forms('prevent avoid minimize minimise maximise maximize')
PRESERVE = forms('maintain keep preserve retain') | {'kept', 'keeping'}
CREATE = forms('make create produce generate form shape') | {'made', 'making'}
PROVIDE = forms('provide give leave yield') | {'gave', 'given', 'left'}
ADAPT = forms('match satisfy accommodate meet conform suit fit align reflect')
ADAPT |= {'met'}
IMPROVE = forms('reduce improve increase achieve obtain reach '
                'enhance promote encourage')
HELP = forms('help support facilitate handle cover include show offer')
CHECK = forms('check verify confirm assert test')
DESIRE = forms('want wish desire')
NEED = forms('need require')
MODALS = {'can', 'could', 'will', 'would', 'should', 'must', 'may', 'might'}

VERB_CUES = ((ENSURE, 0.99), (ENABLE, 1.1), (PREVENT, 1),
              (PRESERVE, 0.55), (CREATE, 0.13), (PROVIDE, 0.36),
              (ADAPT, 0.14), (IMPROVE, 0.073), (HELP, 0.091))
STRONG_INFINITIVES = ENABLE | ADAPT
OUTCOME_VERBS = ENABLE | PROVIDE
STATE_MATCHING = PRESERVE | ADAPT
CAUSATIVE = CREATE | PROVIDE | IMPROVE
CLAUSE_CHECKS = ENSURE | CHECK | NEED | {'sure', 'condition'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
