        if prev == 'to':
            value += 0.7
            if word in STRONG_INFINITIVES:
                value += 0.84
            if prev_raw == 'To':
                value += 1.1
            if before == 'order':
                value += 0.79
            if before in {'so', 'but'}:
                value += 0.97
        if prev == 'while':
            value += 2.1
        if prev == 'still':
            value += 0.89
        if prev in MODALS:
            value += 0.32
        if prev in {'this', 'that'} and word in OUTCOME_VERBS:
            value += 0.59
