        elif prev == 'such':
            value = 3.3
        elif prev in {'way', 'manner'}:
            value = 3.1
            if before in {'a', 'such'}:
                value += 1.3
        elif prev in {'ways', 'enough'}:
            value = 1.5
        elif prev in {'one', 'something', 'given', 'suppose'}:
            value = 0.67
        elif prev in CLAUSE_CHECKS:
            value = 0.78
        elif prev in {'is', 'means'}:
            value = 0.17
    if word == 'sure':
        value = 1.6 if prev in CREATE else 0.09
    if word == 'still':
        value = 3.9 if prev == 'while' else 1.2 if prev == 'but' else 0.14
    if word == 'way':
        value = 0.17
        if prev in {'this', 'that'}:
            value = 6 if prev_raw in {'This', 'That'} else 3.4
        elif prev == 'a' and before == 'such':
            value = 2.9
        elif prev in {'a', 'some', 'either', 'any'}:
            value = 0.8
    if word == 'possible' and prev == 'as':
        value = 1.3
    if word in {'where', 'whether'}:
        value = 0.42
    if word == 'to':
        value = -0.02
        if prev in {'order', 'leading', 'lead', 'leads', 'according'}:
            value = 0.33
        elif prev in {'is', 'are', 'was', 'were'}:
            value = 0.26
            purpose_words = ('goal', 'purpose', 'objective', 'mission', 'aim')
            if any(w in recent.split() for w in purpose_words):
                value += 0.97
        elif prev == 'as':
            value = 1.1
        elif prev in {'cater', 'conform', 'suited'}:
            value = 0.97
    if word == 'if' and prev in CHECK:
        value = 0.73
    if word == 'in' and prev in {'result', 'resulting', 'results'}:
        value = 0.58
    if word == 'from' and prev == 'away':
        value = 0.82
    if word == 'on' and prev == 'based':
        value = 0.7
    if word == 'of' and prev == 'instead':
        value = 0.64
    if word == 'as' and prev == 'long':
        value = 0.84
    if word == 'for' and prev == 'order':
        value = 1.5

    # The object of an action may itself carry the desired-state signal.
    if word in {'the', 'a', 'an', 'it', 'them', 'this'}:
        if prev in STATE_MATCHING:
            value = 0.52
        elif prev in CAUSATIVE:
            value = 0.18
        if word == 'it' and prev in CREATE:
            value = 0.84
    if word in {'have', 'get'} and prev == 'to':
        value = 1.6 if prev_raw == 'To' else 0.65
    if word in {'without', 'something', 'until'}:
        value = 0.32
    if word in {'will', 'would'}:
        value = 0.65 if prev in {'this', 'that'} else -0.042
    if word == 'which':
        value = -0.096

    # Chinese equivalents: enabling, avoiding a consequence, "in this way".
    if word in {'这样', '這樣'}:
        value = 3.6 if prev == '，' else 0.9
    elif word in {'让', '讓', '使', '使得', '为了让', '為了讓'}:
        value = 1
        if prev in {'为了', '為了', '以'}:
            value = 3.5
        elif prev == '，':
            value = 1.7
    elif word in {'以免', '以便'}:
        value = 2.7
    elif word in {
        '确保', '確保', '保证', '保證', '符合', '满足', '滿足', '避免', '防止'
    }:
        value = 1.4
        if prev == '以':
            value += 1.5
    elif word in {'从而', '從而'}:
        value = 0.84

    # Other languages' purpose/complement markers and manner constructions.
    if word == 'чтобы':  # Russian: in order that
        value = 1.7
    elif word in {'dass', 'daß'}:
        value = 3 if prev == 'so' else 1.3
    elif word == 'um':
        value = 1.1 if prev == ',' else 0.093
    elif word in {'que', 'che'}:
        value = 2.1 if prev in {'para', 'pour', 'afin', 'tanto'} else 0.23
    elif word in {'forma', 'forme', 'modo', 'manera', 'manière'}:
        value = 1.3 if prev in {'de', 'in', 'la', 'une'} else 0.57
    elif word.startswith('garant'):  # Romance guarantee stems
        value = 1.4
    # Japanese connective and conditional verb endings.
    elif word in {'して', 'って', 'て', 'いて', 'えて', 'ければ'}:
        value = 0.91

    recent = (recent + raw.lower())[-70:]
    return (doc, raw.strip(), prev, recent), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:3426 -- the "purpose / result connective" component.

What it does: it fires on the word that opens a clause giving the purpose, result or
intended effect of what came before. Its strongest case is "that" in "so that", "such
that" and "in such a way that" (about 4 in activation units on average); next is "way" in
"in this way" (about 2.6), then verbs that name a goal or effect the action is aimed
at: ensure, allow, avoid, prevent, maximize, keep, maintain, enable, and their foreign
equivalents (чтобы, dass, 确保, 这样). "that" after requirement verbs (ensure/verify/
check/given/suppose that) is weaker, and all other tokens are about zero.

The program is a lookup on the current word and the word before it. It explains about a
fifth of the variance: most of the component's activity is small and diffuse.
"""
READS = ()

RESULT_HEADS = {" so", " such", " way"}
REQUIRE_HEADS = {" ensure", " ensures", " ensuring", " ensured", " verify", " check", " confirm",
                 " require", " requires", " given", " provided", " suppose", " hope", " hoping",
                 " sure", " condition"}
STRONG_GOAL = {" ensure", " ensures", " ensuring", " ensured", " assure", " guarantee", " allow",
               " allows", " allowing", " avoid", " avoids", " avoiding", " prevent", " prevents",
               " preventing", " minimize", " minimizing", " maximize", " maximizing", " maintain",
               " maintains", " maintaining", " keep", " keeps", " keeping", " preserve",
               " preserving", " retain", " enable", " enables", " enabling", " facilitate",
               " accommodate", " satisfy", " satisfies", " satisfying", " suit", " promote",
               " foster", " enhance", " encourage", " optimize", " permit", " permits"}
WEAK_GOAL = {" achieve", " reduce", " meet", " obtain", " boost", " align", " leave", " leaving",
             " letting", " provide", " help", " helps", " give", " gives", " make", " sure",
             " show", " include", " fit", " match", " get", " still"}
WANT = {" want", " wanted", " wants"}
PURPOSE_OTHER = {"确保", "保证", "为了", "这样", "чтобы", " dass", " daß", " afin", "使得", "让",
                 "讓", "以便"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    # the word before, unless the document starts here
    same_doc = len(toks) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = toks[-2] if same_doc else ""
    if cur == " that":
        if prev in RESULT_HEADS:
            return carry, 3.8
        return carry, (0.9 if prev in REQUIRE_HEADS else 0.15)
    if cur == " way":
        if prev == " this":
            return carry, 2.6
        return carry, (1.2 if prev in {" a", " such"} else 0.0)
    if cur == " to" and prev in {" as", " order"}:
        return carry, 0.6
    if cur in STRONG_GOAL:
        return carry, 1.2
    if cur in WANT:
        return carry, 1.1
    if cur == " where":
        return carry, 0.55
    if cur in WEAK_GOAL:
        return carry, 0.5
    if cur in PURPOSE_OTHER:
        return carry, 1.25
    return carry, 0.0

programs.sol:
"""Approximate a Romance infinitive-ending detector.

Keep the current word and a running estimate of the text's language. A
Romance infinitive ending gets a negative response when frequency tables
also support a plausible participle or gerund. Endings continuing a split
word get a stronger response. Repeated middle dots get a separate
positive response. Smaller, more diffuse signals are left unmodelled.
"""
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
# The last five languages are competitors, not positive detector classes.
LANGUAGES = ('en', 'fr', 'es', 'pt', 'it', 'de', 'nl', 'pl', 'ro', 'tr')
ENDINGS = (('er', 'ir', 're', 'oir'), ('ar', 'er', 'ir'),
           ('ar', 'er', 'ir'), ('are', 'ere', 'ire'))
# Strength for a whole-word token, then the extra for a word continuation.
STRENGTH = ((-1.8233, -1.3272), (-0.9670, -1.2770),
            (-0.8436, -1.5956), (-1.2792, -1.2128))
WORD = re.compile(r'[^\W\d_]+', re.UNICODE)

@lru_cache(maxsize=100000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)

def language_weights(scores, sharpness):
    largest = max(scores)
    weights = [math.exp(sharpness * (s - largest)) for s in scores]
    total = sum(weights)
    return [w / total for w in weights]

@lru_cache(maxsize=100000)
def verb_evidence(word, lang):
    """Frequency of regular-looking inflected forms, relative to the word."""
    if lang == 'fr':
        stem = word[:-2]
        if word.endswith('er'):
            forms = (stem + 'é', stem + 'ant')
        elif word.endswith('ir'):
            forms = (stem + 'i', stem + 'issant')
            if word.endswith(('tir', 'mir', 'vir', 'nir')):
                forms += (stem + 'ant',)
        elif word.endswith('oir'):
            forms = (word[:-3] + 'ant', word[:-3] + 'u')
        else:
            forms = (stem + 'u', stem + 't', stem + 'ant', word[:-3] + 'ant')
            if word.endswith('ître'):
                forms += (word[:-5] + 'u',)
            if word.endswith('aire'):
                forms += (word[:-4] + 'u',)
    elif lang in ('es', 'pt'):
        stem = word[:-2]
        if word.endswith('ar'):
            forms = (stem + 'ado', stem + 'ando')
        else:
            gerund = 'iendo' if lang == 'es' else (
                'endo' if word.endswith('er') else 'indo')
            forms = (stem + 'ido', stem + gerund)
    else:
        stem = word[:-3]
        if word.endswith('are'):
            forms = (stem + 'ato', stem + 'ando')
        else:
            forms = (stem + ('uto' if word.endswith('ere') else 'ito'),
                     stem + 'endo')
    frequency = max(zipf_frequency(form, lang) for form in forms)
    threshold = max(1.5, zipf_frequency(word, lang) - 2.)
    return 1. / (1. + math.exp(-3. * (frequency - threshold)))

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', [0.] * len(LANGUAGES), 0.)
    _, previous_word, language, count = carry
    text = previous_word + token
    partial = ''
    for match in WORD.finditer(text):
        word = match.group().lower()
        if match.end() == len(text):
            partial = word
        elif len(word) >= 2:
            f = frequencies(word)
            if max(f) >= 3:
                language = [0.9 * a + b for a, b in zip(language, f)]
                count = 0.9 * count + 1
    carry = (document, partial[-60:], language, count)
    context = language_weights([v / max(count, 1) for v in language], 4.)
    f = frequencies(partial) if partial else (0.,) * len(LANGUAGES)
    joint = language_weights(
        [a + 0.5*b/max(count, 1) for a, b in zip(f, language)], 2.)
    continuing = bool(token and token[0].isalpha() and previous_word)
    value = -0.00256
    for i, (endings, strength) in enumerate(zip(ENDINGS, STRENGTH), 1):
        fits = partial.endswith(endings) and token.endswith(endings)
        if i == 1 and partial.endswith('re'):
            # French -re infinitives belong to narrower spelling families;
            # otherwise nouns like 'voiture' would be mistaken for verbs.
            fits = fits and partial.endswith((
                'dre', 'ttre', 'ître', 'être', 'cre', 'ivre', 'uire', 'rire',
                'crire', 'dire', 'lire', 'faire', 'taire', 'plaire',
                'boire', 'croire'))
        if fits:
            evidence = verb_evidence(partial, LANGUAGES[i])
            value += context[i] * joint[i] * evidence * (
                strength[0] + strength[1] * continuing)
    if len(token) >= 2 and set(token) == {'·'}:
        value += 1.2884
    return carry, value

"""A coarse lexical detector around Chinese location/construction markers.

Dictionary glosses classify places, abbreviations and established compounds;
在, motion/direction markers, and demonstratives select fitted class means.
Dictionary senses are not disambiguated. Separate negative offsets handle
repeated interpunct leaders and document-initial whitespace/code openers.
Unrecognized contexts stay near zero. This explains only part of the activity.
"""
from functools import lru_cache
import re
import cedict
import jmdict
import pycountry

READS = ()
COUNTRIES = {c.name.lower() for c in pycountry.countries}
COUNTRIES |= {
    'china', 'taiwan', 'usa', 'england', 'south korea', 'north korea',
    'europe', 'asia', 'africa', 'oceania', 'the americas',
}
GEOGRAPHY = re.compile(
    r'\b(city|county|town|province|prefecture|municipality|capital|district|'
    r'village|place names|Europe|Asia|Africa|Oceania|Americas)\b'
)
PLACE = re.compile(
    r'\b(school|hospital|university|park|station|home|house|office|warehouse|'
    r'storehouse|library|workplace|room|building|place|local|here|there|'
    r'region|area|location)\b'
)
LOCAL = {
    '这里', '這裡', '這裏', '这儿', '這兒', '那里', '那裡', '那儿',
    '當地', '当地', '何处', '何處', '哪里', '哪裡', '哪儿',
    '外面', '地', '家', '旁',
}
# Come, go, return, enter, arrive, toward, against, reside, visit, migrate, etc.
SELECTORS = set('来來去回归歸赴入返到往向对對驻駐留居抵访訪迁遷输輸退')


def first_sense(gloss):
    return re.sub(r'\([^)]*\)', '', gloss).strip().split(';')[0].lower()


@lru_cache(None)
def category(s):
    if s in {'此', '这', '這', '那'}:
        return 'demonstrative_' + s
    if s in set('中内內上下前后後'):
        return 'spatial'
    if s in {'于', '於', '自', '自我', '自己'}:
        return 'abstract_relation'
    if s in LOCAL:
        return 'local'
    glosses = cedict.glosses(s)
    country = any(first_sense(g) in COUNTRIES for g in glosses)
    short_name = country or any(
        re.search(r'(?:abbr\.|abbreviation|short name).*?\b[A-Z][a-z]{2}', g)
        or re.match(r'[A-Z][a-z].*\(abbr', g)
        for g in glosses
    )
    if len(s) == 1 and short_name:
        return 'geo_short'
    if country or any(GEOGRAPHY.search(g) for g in glosses):
        return 'geo_full'
    if s in set('东西南北東'):
        return 'compass'
    if any(PLACE.search(g) for g in glosses):
        return 'place'
    if any(re.match(
        r'to (think|consider|want|see|look|watch|hear|listen|come|go)\b', g
    ) for g in glosses):
        return 'mental_motion'
    if s in {'更多', '不断', '不斷', '一直', '进一步', '進一步'}:
        return 'aspect'
    return 'other'


@lru_cache(None)
def compound(p, s):
    return bool(cedict.glosses(p + s) or jmdict.glosses(p + s))


def group(p, s):
    s, p = s.strip(), p.strip()
    if s in {'在线', '在線'} or (p.endswith('在') and s in {'线', '線'}):
        return 'online'
    if s.startswith('在') and len(s) > 1:
        return 'fused_' + category(s[1:])
    if not p:
        return 'base'
    if p[-1] not in SELECTORS and not p.endswith('在'):
        return 'base'
    c = category(s)
    special = c in {
        'spatial', 'abstract_relation', 'geo_short', 'geo_full',
        'local', 'compass',
    } or c.startswith('demonstrative')
    if p.endswith('在'):
        if special or c == 'mental_motion':
            return 'zai_' + c
        if compound('在', s):
            return 'zai_compound'
        return 'zai_' + c
    if special:
        return 'direction_' + c
    if jmdict.glosses(p[-1] + s):
        return 'direction_japanese_compound'
    return 'base'


# zai: previous token ends in 在; fused: current token starts in 在.
VALUES = {
    "initial_whitespace": -0.3,
    "initial_code_marker": -0.25,
    "initial_code_keyword": -0.82,
    "zai_compound": -0.52,
    "zai_demonstrative_此": -3.74,
    "direction_japanese_compound": -0.8,
    "fused_local": -0.61,
    "zai_place": -0.21,
    "zai_geo_full": -0.42,
    "direction_geo_short": -1.7,
    "fused_place": -0.38,
    "direction_geo_full": -0.17,
    "zai_local": -1.16,
    "zai_spatial": 0.92,
    "zai_demonstrative_這": -1.46,
    "direction_demonstrative_这": -0.45,
    "direction_spatial": 0.15,
    "zai_abstract_relation": 1.33,
    "online": -1.55,
    "zai_geo_short": -0.81,
    "fused_geo_full": -0.32,
    "zai_mental_motion": 0.84,
    "fused_demonstrative_这": -1.24,
    "direction_demonstrative_此": -0.37,
    "fused_demonstrative_此": -1.52,
    "direction_demonstrative_那": -0.76,
    "zai_demonstrative_这": -1.93,
    "fused_geo_short": 0.26,
    "direction_demonstrative_這": -0.51,
    "zai_aspect": 0.42,
    "zai_demonstrative_那": -1.8
}


# Document-initial programming-language declaration/import words.
CODE_WORDS = {
    'import', 'package', 'const', 'var', 'function', 'func', 'def', 'class',
    'int', 'let', 'public', 'private', 'from', 'using', 'namespace', 'include',
}


def step(carry, prefix, upstream):
    current = prefix.token_strings[-1]
    first = (not prefix.position or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if first else prefix.token_strings[-2]
    # Repeated interpunct leaders have a separate negative response.
    s = current.strip()
    if len(s) >= 2 and not s.strip('·'):
        return None, -1.44
    g = group(previous, current)
    if g == 'base' and first:
        if not s:
            g = 'initial_whitespace'
        elif s in CODE_WORDS:
            g = 'initial_code_keyword'
        elif s.startswith(('#', '/', '<', '>', '*')):
            g = 'initial_code_marker'
    return None, VALUES.get(g, 0.0016)

programs.haiku:
"""A few concept rules for layers.1.mlp.down_proj:3430, one MLP neuron of layer 1.

The neuron is quiet almost everywhere (typical size 0.05). It goes clearly negative in
three places, all in Chinese text:
  1. on the character right after a verb of going, coming, leaving or staying
     (来, 赴, 返, 离, 驻, 留, 入, 抵, 回, 退, 旅 ...) or after 在, when that character
     abbreviates a country, region or city: 来[华], 赴[美], 返[台], 离[港], 驻[泰], 在[台]
     (strongest, around -1.9);
  2. more weakly on other single characters right after such a verb, e.g. 来[店], 入[会],
     离[线] (around -0.16);
  3. on locative compounds that start with 在: 在线 (online), 在这里, 在此, 在家 (around -0.6);
  4. weakly, on the first token of a new document: negative when it is not a plain
     English word (code, punctuation, a Chinese character), slightly positive when it is.
Everything else is predicted as 0.
"""
READS = ()

# verbs of going, coming, leaving, staying, returning; 在 is the locative preposition
MOTION_VERBS = set("来赴返离驻留入抵回退旅到去出往反在")
# single characters that abbreviate countries, regions and cities
PLACE_CHARS = set("华美台臺港澳泰欧俄英法德日韩越印荷穗泉汕沪京蜀粤")

# mean activations per group, measured on training rows
PLACE_AFTER_MOTION = -1.9
CHAR_AFTER_MOTION = -0.16
ZAI_COMPOUND = -0.6
DOC_START_WORD = 0.04
DOC_START_OTHER = -0.11


def is_han(s):
    return len(s) > 0 and all("一" <= c <= "鿿" for c in s)


def is_ascii_letter(s):
    return len(s) > 0 and s[0].isascii() and s[0].isalpha()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, DOC_START_WORD if is_ascii_letter(tok) else DOC_START_OTHER
    prev = prefix.token_strings[-2]
    if prev in MOTION_VERBS and is_han(tok):
        if tok[0] in PLACE_CHARS:
            return carry, PLACE_AFTER_MOTION
        if prev != "在":
            return carry, CHAR_AFTER_MOTION
    if is_han(tok) and tok[0] == "在" and len(tok) > 1:
        return carry, ZAI_COMPOUND
    return carry, 0.0

programs.sol:
"""Two-context approximation, not a full parser.

Negative Japanese responses follow predicate-like kana endings, especially
before particles and nominalizing words. The second mode reads names after
opening/closing angle brackets, distinguishes common HTML tags from other
identifiers, and ignores the doubled << stream/shift operator. Context resets
at document boundaries. Unrecognized contexts predict zero.
"""
import regex

READS = ()

# Common current and legacy HTML element names.
HTML = frozenset('''a abbr address area article aside audio b base bdi bdo
blockquote body br button canvas caption cite code col colgroup data datalist
dd del details dfn dialog div dl dt em embed fieldset figcaption figure footer
form h1 h2 h3 h4 h5 h6 head header hgroup hr html i iframe img input ins kbd
label legend li link main map mark menu meta meter nav noscript object ol
optgroup option output p param picture pre progress q rp rt ruby s samp script
search section select slot small source span strong style sub summary sup
table tbody td template textarea tfoot th thead time title tr track u ul var
video wbr font center big tt strike frame frameset'''.split())

def ending_factors(s):
    """Ordinary continuations and sentence particles have different strengths."""
    if s.endswith(('です', 'ます', 'ません')):
        return 0.8, 0.8
    if s.endswith(('する', 'す')):
        return 1.3, 1.2
    if s.endswith(('く',)):
        return 0.7, 0.2
    if s.endswith(('う', 'つ')):
        return 0.7, 0.4
    if s.endswith(('る', 'ぐ', 'ぬ', 'ぶ', 'む')):
        return 1.0, 1.0
    if s.endswith(('い',)):
        return 0.5, 0.7
    if s.endswith(('た',)):
        return 0.4, 0.4
    if s.endswith(('だ',)):
        return 0.5, 0.5
    if s == 'よ':
        return 0.1, 0.3
    return 0.0, 0.0

# Clause-ending particles: and, question, contrast, emphasis, etc.
PARTICLES = {
    'し': 12.9,
    'か': 9.1,
    'が': 8.0,
    'な': 10.1,
    'よ': 9.6,
    'ね': 2.6,
    'わ': 3.2,
}

# Standalone forms; longer tokens are handled by the families below.
EXACT = {
    'の': 8.0,  # nominalizer
    'よう': 8.3,  # manner
    '様': 8.3,  # manner
    'と': 7.2,  # quotation
    'とい': 6.1,  # quotation fragment
    'ほ': 7.7,  # beginning of ほど (degree)
    'た': 7.7,  # beginning of ため / たび (purpose / frequency)
}
PREFIXES = (
    (('の',), 3.0),  # nominalizer compound
    (('もの',), 6.1),  # thing
    (('こと',), 3.0),  # fact
    (('よう',), 4.4),  # manner compound
    (('ため',), 6.0),  # purpose
    (('とい', 'と思'), 4.3),  # quotation compound
    (('だけ', 'ほど', 'くらい', 'ぐらい'), 7.7),  # degree
    (('から', 'らしい', 'ところ', 'わけ', 'はず',
      'べき', 'とも', 'との', 'んだ'), 5.2),  # connective
    (('者', '事', '上', '場合', '力', '時', '方',
      '方法', '必要', '所', '間'), 5.1),  # abstract noun
