def japanese(previous, current):
    ordinary, final = ending_factors(previous)
    if ordinary == 0.0 and final == 0.0:
        return 0.0
    if current in PARTICLES:
        return -final * PARTICLES[current]
    magnitude = EXACT.get(current)
    if magnitude is None:
        for beginnings, strength in PREFIXES:
            if current.startswith(beginnings):
                magnitude = strength
                break
