    if '"""' in s:
        value += 0.53
        if raw[:1].isspace():
            value += 0.57
        if '\n' in raw:
            value -= 0.31
    if '```' in s:
        value += 0.65
    elif '``' in s:
        value += 0.29
    if s == "''":
        value += 0.32
    if s.startswith('\\['):
        value += 0.24
    if s.startswith('[') and previous.rstrip().endswith('\\'):
        value += 0.14
    return None, value

