# Prepositions that can head "<prep> which" relative clauses.
RELATIVE_PREPS = {"in", "by", "with", "to", "at", "from", "on", "within", "through", "under", "during", "upon"}
# Words that can precede a wh-word or noun in a way that starts a clause (includes "of", "about", ...).
PREPOSITIONS = RELATIVE_PREPS | {"of", "about", "and", "is", "was", "for"}
WAY_NOUNS = {"way", "ways"}
RELATIONAL_NOUNS = {"time", "times", "day", "date", "year", "place", "places", "role", "reason", "reasons",
                    "extent", "degree", "order", "speed", "rate", "impact", "distance", "amount", "effect",
                    "moment", "manner"}
WAY_DETERMINERS = {"the", "only", "same", "best", "first", "right", "specific", "various", "one"}
TIME_COUNTERS = {"every", "each", "many", "next", "average", "last", "another"}
DEGREE_ADVERBS = {"well", "fast", "quickly", "badly", "deeply", "often", "efficiently"}
DEGREE_ADJECTIVES = {"far", "long", "much", "hard", "easy", "high", "large", "big", "important", "quick", "slow", "soon"}


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    tok = strings[-1].strip().lower()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = strings[-2].strip().lower()

    value = 0.0
    if tok in WAY_NOUNS:
        if prev in WAY_DETERMINERS:
            value = -4.5
        elif prev in ("another", "many"):
            value = -2.0
    elif tok == "times":
        value = -3.5 if prev in ("of", "many") else -1.0
    elif tok == "time":
        if prev == "first":
            value = -3.0
        elif prev in TIME_COUNTERS:
            value = -2.0
        elif prev == "of":
            value = -1.0
        elif prev == "the":
            value = -1.7
    elif tok in RELATIONAL_NOUNS:
        if prev == "the":
            value = -1.5
    elif tok in ("which", "when", "where", "why") and prev in RELATIONAL_NOUNS | WAY_NOUNS:
        value = -3.0
    elif tok == "that" and prev in RELATIONAL_NOUNS | WAY_NOUNS:
        value = -1.0
    elif tok == "which" and prev in RELATIVE_PREPS:
        value = -2.5
    elif tok == "not" and prev == "or":
        value = -2.0
    elif tok == "as" and prev == "same":
        value = 1.5
    elif tok == "how":
        value = -2.5 if prev in PREPOSITIONS else -1.0
    elif prev == "how" and tok in DEGREE_ADVERBS:
        value = -6.0
    elif prev == "how" and tok in DEGREE_ADJECTIVES:
        value = -3.0
    elif tok in ("what", "where", "why"):
        value = -2.5 if prev in ("is", "'s", "’s", "of") else -0.8
    return carry, float(value)

