"""Sparse spelling, typeface, and publication-label cues.

Font spellings are positive, especially split f+ont and capital .Font.
Source/photo credits and some Chinese publishing/UI labels are also positive.
HTML URL-opening quotes and the spellings Funn/FTE are negative. FontSize-like
identifiers and French verb 'font' are much weaker than the noun. Everything
else is zero. An 80-character tail is reset at each document boundary.
"""
import re

READS = ()
SOURCE_LABELS = {'source', 'photo', 'foto', 'credit', 'quelle'}
AUTHOR_LABELS = {'author', 'authors', 'publisher', 'copyright', 'by'}
FRENCH_VERB_PREFIXES = {
    'ils', 'elles', 'qui', 'que', 'ne', 'se', 'nous', 'vous', 'me', 'te',
    'en', 'leur', "'ils", "'elles", "'en",
}
CHINESE_SOURCE = ('来源', '來源', '摘自', '转载自', '轉載自')
CHINESE_METADATA = (
    '作者', '编辑', '編輯', '发布者', '發布者', '分类', '分類', '类别',
    '類別', '类型', '類型', '发表时间', '發表時間',
)


def activation(token, before, previous):
    s, p = token.strip(), previous.strip()
    low, past = s.lower(), before.rstrip()
    pl = past.lower()

    # Typeface words, including completions across tokenizer boundaries.
    if low.endswith(('typeface', 'typefaces')):
        return 1.3
    if pl.endswith('type') and low in {'face', 'faces', 'font'}:
        return 10.5
    if s in {'字体', '字體'}:
        return 4.5
    if s in {'体', '體'} and past.endswith('字'):
        return 8.6
    if 'font' in low:
        if re.search(r'font(?:size|weight|style|awesome|ofsize)', low):
            return 0.5
        if low == 'font' and p.lower() in FRENCH_VERB_PREFIXES:
            return 0.85
        if s.startswith('.Font'):
            return 7.3
        if pl.endswith('</'):
            return 1.2
        if low.startswith('(font'):
            return 2.9
        if s.isupper():
            return 4.0
        if 'Font' in s or low.endswith('fonts'):
            return 4.9
        return 4.2
    if low == 'fond':
        return 0.9
    if pl.endswith('font') and token == s:
        if s in {'e', 'i', 'ON'}:
            return 2.4
        if s == '-family':
            return 5.0
        if s == '-':
            return 2.2
        if s in {'-style', '-weight'}:
            return 1.1

    # Publishing credits and HTML attribute openings.
    if low in {':', '：'}:
        if past.endswith(CHINESE_SOURCE):
            return 4.2
        if past.endswith(CHINESE_METADATA):
            return 1.8
        word = re.search(r'(\w+)$', past)
        word = word[1].lower() if word else ''
        if word in SOURCE_LABELS:
            return 1.6
        if word in AUTHOR_LABELS:
            return 0.5
        if pl.endswith('font-family'):
            return 1.5
    if s.startswith(('="', "='", '=\\"')):
        if p in {'href', 'src'}:
            return -1.8 if s.startswith('="') else -1.0
        if p in {'target', 'name', 'style', 'class'}:
            return -0.5
    if low == 'on' and p.lower() in {'published', 'updated', 'created', 'posted'}:
        return 0.75 if p.lower() == 'posted' else 1.3
    if s == "'@" and p == 'from':
        return 3.4
    if low == '"fmt':
        return -2.3

    # Other short spelling continuations, not general word semantics.
    if pl.endswith('f') and token == s:
        if low == 'ont':
            return 7.7
        if low.startswith('on'):
            return 1.2
        if low == 'mt':
            return 1.0
        if low == 'nt':
            return 3.5
        if low == 'uentes':
            return 4.8
        if low == 'unn' and previous.rstrip().endswith('F'):
            return -1.8
        if s == 'TE' and previous.rstrip().endswith('F'):
            return -0.8
    if s == 'о' and re.search(r'[Фф](?:от)?$', past):
        return 3.2
    if s == 'от' and past.endswith(('ф', 'Ф')):
        return 1.6

    # Chinese source, writing, and screen-navigation phrases.
    if s in {'来源', '來源'}:
        return 4.7 if past.endswith(('本文', '文章')) else 1.2
    if s == '上' and past.endswith(('左', '右')):
        return 1.6
    if s == '角' and past.endswith(('左上', '右上')):
        return 4.5
    if s == '关注' and past.endswith(('欢迎', '添加', '我', '角')):
        return 3.0
    if s == '自' and past.endswith(('摘', '轉', '转')):
        return 1.8
    if s == '体' and past.endswith('自'):
        return 1.3
    if s == '字' and past.endswith(('打', '中')):
        return 1.1
    if s == '迹' and past.endswith('字'):
        return 5.2
    if s in {'“', '「'} and past.endswith(('点击', '搜索', '微信')):
        return 2.7
    if s == '下方' and past.endswith('扫描'):
        return 4.0
    if s in {'／', '/'} and past.endswith(('圖', '图')):
        return 2.7
    if s == '©' and p.lower() == 'copyright':
        return 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, previous = '', ''
    else:
        _, before, previous = carry
    token = prefix.token_strings[-1]
    value = activation(token, before, previous)
    return (doc, (before + token)[-80:], token), float(value)

"""A rough signal for document starts and interruptions of running prose.

The first token gets a positive pulse, larger for a word beginning without
leading whitespace. Elsewhere, truncation dots and capitalized sentence
restarts or reference labels get small pulses. Escaped text is slightly
negative. Spaces or capitals after a word-attached hyphen also get a
pulse. These are surface cues, not a grammaticality test.
"""
READS = ()
DETERMINERS = set(
    'a an the this that these those each every any some no another such'.split()
)
STARTERS = set(
    'the this that these those it he she they we there however therefore '
    'thus then furthermore moreover'.split()
)
CONNECTORS = set(
    'however nevertheless therefore moreover furthermore although whereas '
    'consequently likewise similarly hence thus meanwhile'.split()
)
REFERENCES = set(
    'fig figs figure figures table tables eq eqs equation equations '
    'theorem lemma'.split()
)
FUNCTION_WORDS = DETERMINERS | set(
    'of in on at to for from with by as into over under through about between '
    'and or but nor yet so if when while because although than whether '
    'is am are was were be been being has have had do does did can could '
    'will would shall should may might must i you he she it we they me him '
    'her us them one there who which what'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    word = text.strip()
    lower = word.lower()
    if carry is None or carry != doc:
        if text.startswith('<|'):
            value = 0.49
        elif '\n' in text or '\r' in text:
            value = 0.15
        elif text and text[0].isalpha():
            value = 0.33 if lower in DETERMINERS else 0.56
        elif word.isascii() and word.isalpha():
            value = 0.43
        else:
            value = 0.31
        return doc, value

    previous = prefix.token_strings[-2]
    prev_word = previous.strip()
    capital = text.startswith(' ') and (word.istitle() or word.isupper())
    value = -0.002
    if '...' in text or '…' in text:
        value += 0.083
    if '\\' in text:
        value -= 0.021
    if capital and previous and previous[-1].isalpha():
        if lower in STARTERS:
            value += 0.069
        if lower in CONNECTORS:
            value += 0.102
        if lower in REFERENCES:
            value += 0.045
    if capital and lower in STARTERS and prev_word.lower() in FUNCTION_WORDS:
        value += 0.015
    if capital and lower in REFERENCES and previous.isspace():
        value += 0.232
    attached_hyphen = False
    if previous.endswith(('-', '–', '—')):
        attached_hyphen = len(previous) > 1 and previous[-2].isalpha()
        if len(previous) == 1 and len(prefix.token_strings) > 2:
            if prefix.document_ids[-3] == doc:
                before = prefix.token_strings[-3]
                attached_hyphen = bool(before) and before[-1].isalpha()
    if attached_hyphen:
        if text.isspace():
            value += 0.4
        elif capital and word.isalpha():
            value += 0.35
    return doc, value

"""Sparse surface-form pulses, chiefly for exec/eval and e-linked fragments.

Execution/evaluation fragments are negative, especially in shell commands.
Smaller rules cover interpreter paths, the surname marker 姓, split flag
and animal emoji, title headers, and repeated middle dots. Most positions
are zero. This is a mixed spelling detector, not one semantic category.
