import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_bytes, position, beginning = '', b'', 0, ''
    else:
        _, previous, previous_bytes, position, beginning = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    word = token.lstrip(' \t\r\n.(/_-')
