    value = 0.0

    if lower in ('exec', 'eval'):
        if word[:1].isupper():
            value = -3.7 if lower == 'exec' else -5.5
        elif token.startswith(('.', '/', '_', '-')):
            value = -4.3 if lower == 'exec' else -5.8
        elif token[:1].isspace():
            value = -8.8 if previous.isspace() else -7.8
        else:
            value = -6.7
        if lower == 'exec':
            if previous.strip().lower() == 'docker':
                value = -17.2
            elif previous == ' -' or previous == '/lib':
                value = -15.0
        elif previous.rstrip().endswith('['):
            value = -10.0
    elif token == '/env':
        if previous == '/bin':
            value = -13.7 if position == 3 and beginning == '#!/usr/bin' else -9.3
        else:
            value = -2.1
    elif token == '/sh' and position == 2 and beginning == '#!/bin':
        value = -6.55
    elif token == '姓':
        value = -8.7
    elif previous_bytes.endswith(b'\xf0\x9f'):
        # Third UTF-8 byte: regional-indicator flags or animal pictographs.
        if raw == b'\x87':
            value = -4.1
        elif raw == b'\x90':
            value = -3.0
    elif token == ':' and position == 1 and previous == 'Title':
        value = 10.95
    elif token and set(token) == {'·'} and len(token) >= 2:
        value = 1.5
    elif previous and token == token.lstrip():
        last = unicodedata.normalize('NFD', previous[-1])[0].lower()
