                value = -8.5 if stem.lower() == 'e' else -3.3
            elif lower in ('vol', 'velo', 'vo'):
                value = -2.4 if previous[-1] in 'éÉ' else -1.4
            elif lower in ('uc', 'ug') and stem.lower() == 'e':
                value = -1.4
            elif lower == 'ol':
                value = -0.8

    if position < 5:
        beginning += token
    return (doc, token, raw, position + 1, beginning), value

"""Approximate several local spelling responses, mostly outside Latin text.

Recognize unfinished Han characters after a space, Greek accented letters
or rho after space-prefixed tau, and selected Asian syllable completions.
Keep separate lexical responses for Chu, Jing, brocade and interpunct runs;
these do not form a claimed semantic category. The constants approximate
training activation levels. Unmatched positions predict zero, so much of
the component's smaller, context-sensitive activity remains unexplained.
Only the current token and the previous token of its document are used.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    b = prefix.token_bytes[-1]
    s = b.decode('utf-8', 'replace')
    same_doc = (len(prefix.token_ids) > 1 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    prev = prefix.token_bytes[-2] if same_doc else b''
    before = prev.decode('utf-8', 'replace')
    value = 0.0

    # Runs of two or more interpuncts.
    if len(s) >= 2 and not s.strip('·'):
        value = -1.23

    # Individual Han tokens: Chu, Jing (thorn), and brocade.
    if s == '楚':
        value = 6.0 if before in ('吴', '吳') else 4.1
    elif s == '荆':
        value = 8.8
    elif s == '锦':
        value = 5.9
    elif b == b'\xe9\x8c':  # unfinished traditional metal-radical Han
        value = 0.8
    elif prev.endswith(b'\xe9\x8c') and b == b'\xa6':  # 錦
        value = 10.5

    # An unfinished Han character immediately after a space.
    if prev in (b' \xe6', b' \xe8') and len(b) == 1:
        if 0x80 <= b[0] < 0xc0:
            value = 5.1 if b[0] == 0x8d else 0.2
            # The wood-ideograph region U+6800--U+69BF.
            if prev == b' \xe6' and 0xa0 <= b[0] <= 0xa6:
                value = 1.8

    # Unfinished Gurmukhi and Tamil UTF-8 prefixes.
    if b == b'\xe0\xa8':
        value = 0.49
    elif b == b'\xe0\xaf':
        value = 1.4

    # Space-prefixed Greek τ: accented-letter continuations and τρ.
    if before == ' τ' and s and not s.startswith(' '):
        if s == 'ρ':
            value = 1.6
        elif len(s) == 1 and 'GREEK' in unicodedata.name(s, ''):
            decomposed = unicodedata.normalize('NFD', s)
            base, marks = decomposed[0], decomposed[1:]
            if marks:
                value = 1.0
                if base in 'εο' and '\u0301' in marks:
                    value = 2.6
                elif base == 'α':
                    value = 1.8

    # Selected split Vietnamese syllables.
    if s == 'a':
        if before == ' tự':
            value = 6.0
        elif before == ' dự':
            value = 2.5
        elif before in ('ọ', 'ứ'):
            value = 1.0
    if before in (' T', 'T'):
        if s == 'uy':
            value = 1.5
        elif s == 'ứ':
            value = 2.1
    elif before == ' t' and s == 'ết':  # Tết
        value = 1.4
    if before == 'ù' and s == 'y':
        value = 2.45

    # The Thai syllable 'tit' and Japanese syllable 'jin'.
    if before == 'ต' and s == 'ิด':
        value = 4.0
    elif before == 'じ' and s == 'ん':
        value = -1.5

    return None, value

