"""Approximate short y-bearing word fragments by familiar spelling patterns.

Ignore complete tokens beginning a word. On continuations, distinguish
vowel+y, sibilant+y, consonant+y, vowel-consonant+y, and English suffixes.
Capitalization and unfinished-word length modify these responses. A y at
the start of a piece also uses the preceding letters; an immediately
following a can retain a negative response. Double middle dots have a
separate negative response. This is an incomplete spelling approximation.
"""
import re

READS = ()
VOWELS = 'aeiou'
SUFFIXES = {'ly', 'ally', 'ily', 'ely', 'ity', 'ary', 'ery', 'ory',
            'ety', 'acy'}


def predict(token, previous, word, first):
    low = token.lower().strip()
    prev = previous.lower().strip()
    proper = word[:1].isupper()
    long = len(word) > 8
    if '··' in token:
        return -1.05
    if low == 'a' and 'y' in prev:
        return -0.55 - 0.8 * proper
    if 'y' not in low or len(low) > 4:
        return 0.0
    if token[:1].isspace():
        return (-0.29 if len(low) == 2 and low.endswith('y')
                and low not in {'by', 'my'} else 0.0)
    if first or len(word) <= len(low):
        return 0.0
    y = low.rfind('y')
    if low in SUFFIXES:
        value = -0.17 - 0.17 * proper + 0.15 * long
    elif y == 0:
        if len(low) == 1:
            value = -0.05 - 0.28 * proper - 0.05 * long
        else:
            value = -0.10 - 0.11 * proper + 0.20 * long
    elif y == 1 and len(low) == 2:
        if low[0] in VOWELS:
            value = 0.11
        elif low[0] in 'csz':
            value = 0.8 + 0.22 * proper - 0.3 * long
        else:
            value = -0.08 - 0.07 * proper
    elif y >= 2 and low[y-2] in VOWELS and low[y-1] not in VOWELS:
        value = -0.28 - 0.62 * proper + 0.15 * long
    else:
        value = -0.04 * proper
    if y == 0:
        c = prev[-1:]
        value += 0.07 * (len(low) - 1)
        if c:
            if c in VOWELS:
                value += 0.21
            elif c in 'td':
                value -= 0.35
            elif c in 'mn':
                value -= 0.03
            elif c in 'lr':
                value += 0.18
            elif c in 'csz':
                value += 0.12
        if len(prev) >= 2 and prev[-2] in VOWELS and c not in VOWELS:
            value -= 0.48
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, word = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    pieces = re.split(r'[^\w]', token)
    word = (pieces[-1] if len(pieces) > 1 else word + token)[-80:]
    value = predict(token, previous, word, first)
    return (doc, token, word), float(value)

"""Approximate a contrast in short Slavic spelling fragments.

Vowel + iotated vowel favors the positive side (especially after i).
Softened n/l/r favors the negative side. The response depends strongly on
whether the spelling is split across tokens; long and space-led pieces
are much weaker. Latin j and palatal consonant spellings get related rules.
Separate rules handle em dashes and centered-dot filler runs.
This is a spelling heuristic, not a complete phonetic transcription.
"""
READS = ()
VOWELS = set('аеёиоуыэюяіїєaeiouy')
CONSONANTS = set('бвгджзклмнпрстфхцчшщ')

# Each pair is (a lone vowel after this consonant, an internal spelling).
# Columns: ya, yu/yo, soft sign.  n, l and r have distinct responses.
SOFTENING = {
    'н': ((-4.9, -3.7), (-1.0, -1.2), (-2.6, -2.3)),
    'л': ((-3.6, -2.4), (-2.0, -1.1), (-1.5, -0.3)),
    'р': ((-2.8, -1.9), (-1.8, -1.6), (-1.8, -1.0)),
}


def spelling_value(text, previous):
    raw = text.lstrip()
    word = previous.strip()
    leading = text[:1].isspace()
    latin_word = (not leading and len(word) >= 3 and word.isalpha()
                  and word[-1:].islower())
    text, previous = text.lower(), previous.lower()
    s = text.lstrip()
    if not s or len(text) > 7:
        return 0.0
    if leading and s in ('я', 'ю', 'ё'):
        return 0.3
    value = 0.0
    for i, c in enumerate(s):
        b = s[i-1] if i else (previous[-1:] if not leading else '')
        if not b:
            if c in 'яюё':
                value += 0.4
            continue
        boundary = i == 0
        # Positive: a glide separated from a preceding vowel.
        if c in 'яюёеєйиі' and b in VOWELS:
            if b in 'иі':
                if c in 'яюё':
                    value += 2.9 if boundary else (1.6 if i == 1 else 0.6)
                elif c in 'иі':
                    value += 1.8 if boundary else 1.0
                elif c in 'еє':
                    value += 1.4 if boundary else 0.7
                else:
                    value += 1.0 if i == 1 else (0.5 if boundary else 0.3)
            elif b in 'еє' and boundary:
                value += 1.7 if c in 'яюё' else 0.4
            elif c in 'яюё' and boundary:
                value += 0.15
        elif c in 'яюёеє' and b in 'ьъ':
            value += (1.3 if c == 'я' else 0.6) if boundary else 1.3
        # Negative: a palatalizing letter attached to a consonant.
        elif b in CONSONANTS:
            if c in 'яюёь':
                column = 0 if c == 'я' else (2 if c == 'ь' else 1)
                if b in SOFTENING:
                    lone, internal = SOFTENING[b][column]
                    if boundary and len(s) > 1:
                        lone *= 0.35 if len(s) <= 3 else 0.05
                    value += lone if boundary else internal
                elif b in 'дтз':
                    amount = (1.9 if c == 'я' else 2.3) if c in 'яюё' else 0.3
                    value -= amount * (0.2 if boundary and len(s) > 1 else 1.0)
                elif boundary:
                    amount = 1.0 if c in 'яюё' else 0.2
                    value -= amount * (0.15 if len(s) > 1 else 1.0)
            elif c in 'еєиі' and b in 'нл' and not boundary:
                value -= 0.4
        # Latin spellings: distinguish a word continuation from an index j.
        if c == 'j' and raw[i:i+1] == 'j' and (latin_word or i > 1):
            if b == 'c':
                value += 4.0 if boundary and len(s) <= 2 else 0.6
            elif b in 'nl':
                value -= 1.6 if boundary and len(s) <= 2 else 0.5
            elif b in 'ey' and boundary and len(s) <= 2:
                value += 1.7 if b == 'e' else 2.5
            elif b == 'i':
                value += 0.5
