"""layers.1.mlp.down_proj:3447 -- a Russian/Ukrainian word-ending detector with a sign flip.

Plain-language reading: this component fires on the last piece of a Cyrillic word when
that piece is a common ending, and its sign says whether the word is a verb form or a noun.
- Verb-like endings (-ля, -ня, -ря, -ень, -ять, -ё, -лю, -ляет/-ляют ...) push it negative.
- Noun/adjective endings (-ия, -ий, -ие, -ии, -ья, -ция, -ации, -их) push it positive.
- The sign of a bare -я (and -ю, -ей) depends on the letter before it: after a vowel or a
  soft sign (-ья, -ея, -ия-like nouns) it is positive; after a consonant (verb stems such
  as сохран|яется, пон|ял) it is negative.
- An em dash " —" used in Russian text (definitions: "X — это ...") is mildly positive.
- A run of middle dots (a leader line, "······") is strongly negative.
Everything else predicts 0. The program reads only the current token and the one before it.
"""

READS = ()

VOWELS = set("аеёиоуыэюяіїєaeiouy")
SOFT_SIGN = "ь"

# Verb-form and infinitive endings (sign: negative)
VERB_ENDINGS = {"ля", "ня", "ря", "оля", "еля", "лю", "ё", "ень", "ять",
                "ляет", "ляют", "ляется", "ляю", "юсь"}
# Noun and adjective endings (sign: positive)
NOUN_ENDINGS = {"ия", "ий", "ие", "ии", "ья", "ию", "ция", "ции", "ций", "ации", "их"}


def is_cyrillic(text):
    return any("Ѐ" <= ch <= "ӿ" for ch in text)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    before = prefix.token_strings[-2].strip()[-1:] if len(prefix.token_strings) > 1 else ""
    after_vowel_or_soft = before in VOWELS or before == SOFT_SIGN
    if cur and set(cur) == {"·"}:
        return None, -3.0
    if cur == " —":
        recent = "".join(prefix.token_strings[-12:-1])
        return None, 1.7 if is_cyrillic(recent) else 0.2
    if cur in VERB_ENDINGS:
        return None, -2.3
    if cur in NOUN_ENDINGS:
        return None, 1.4
    if cur == "я":
        return None, 2.5 if after_vowel_or_soft else -2.0
    if cur == "ей":
        return None, 2.6 if after_vowel_or_soft else 0.0
    if cur == "ю":
        return None, 0.8 if after_vowel_or_soft else -1.2
    if cur == "ь":
        return None, -0.8
    if cur == "и" and before in VOWELS:
        return None, 1.1
    return None, 0.0

