    text, consumed = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[consumed:]
    token = prefix.token_strings[-1]
    word = token.strip()
    low = word.lower()
    slide_layout |= bool(re.search(r'\b(\d+)\. \1\.', tail + text))
    value = 0.0

    if low in {'slide', 'slides'}:
        value = 0.4 if token.startswith(' ') else 0.85
    elif low in {'presentation', 'presentations'}:
        value = 0.65 if word[:1].isupper() else 0.28
    elif low in {'powerpoint', 'ppt', 'slideshow'}:
        value = 0.6 if low == 'ppt' else 0.3
    elif low == 'pt' and re.search(r'(?:\.p|\bP)$', tail):
        value = 2.0
    elif low == 'point' and tail.lower().endswith('power'):
        value = 1.2
    elif low in {'outline', 'agenda'}:
        value = 0.6 if word[:1].isupper() else 0.0
    elif low in {'quiz', 'quizzes'}:
        value = 0.25 if word[:1].isupper() else 0.1
    elif low == 'notes':
        value = 0.3 if re.search(r'\b(?:lecture|speaker|study)\s*$', tail, re.I) else 0.08
    elif low in {'guide', 'guides'} and re.search(r'\bstudy\s*$', tail, re.I):
        value = 0.6
    elif low == 'cards' and tail.lower().endswith('flash'):
        value = 2.2
    elif low == 'words' and tail.lower().endswith('cross'):
        value = 0.8
    elif low == 'y' and tail.lower().endswith('jeopard'):
        value = 1.0
    elif low == 'ives' and tail.lower().endswith('object'):
        value = 0.65
    elif low == 'able' and re.search(r'\bbe\s*$', tail, re.I):
        value = -0.04
        if re.search(r'(?:you|students?) (?:should|will|must) be\s*$', tail, re.I):
            value = 0.65
        elif re.search(r'\bBe\s*$', tail):
            value = 0.75
    elif low == 'article' and word.islower():
        value = -0.11
    elif low == 'below' and re.search(r'\b(?:given|described|listed)\s*$', tail):
        value = -0.5
    elif low == 'transcript' and tail.lower().endswith('presentation'):
        value = 2.5
    elif low == 'summary' and tail.lower().endswith('presentation'):
        value = 0.7
    elif low in {'ul', 'li'} and re.search(r'</?$', tail):
        if slide_layout:
            value = 2.3 if low == 'ul' else 0.8
        else:
            value = 0.25 if low == 'ul' else 0.0
    elif token == '://':
        value = -0.14

    if '•' in text:
        value = 0.1
    elif any(c in LEGACY_BULLETS for c in text):
        value = 0.6
    elif word and set(word) == {'·'}:
        value = 0.25 if len(word) > 1 else 0.03
    elif word and set(word) == {','} and len(word) >= 4:
        value = 0.087 * len(word)
    elif token == '\x0c':
        value = 0.23
    elif token == '\\x':
        value = 0.48 if re.search(r'\\n\s*$', tail) else 0.015
    elif token == '\x00':
        value = 0.105
    if token == ',' and tail.endswith('。'):
        value = 0.7
