    if first and token == '<!':
        value = -3.39
    elif first and word == 'Title':
        value = -0.73
    elif token == ':' and tail == 'Title':
        value = -1.56
    elif first and token == '\x00':
        value = 2.23
    elif first and token == ' .':
        value = 1.99
    return (doc, (tail + text)[-300:], pending, slide_layout), value

