"""Slide-deck vocabulary up, bullet separators slightly up, web addresses down.

A diffuse component. Its largest activations are on the pieces of presentation-file
words: "ppt" (as in ".ppt" or "PPT"), "PowerPoint", "slide(s)", "handout", and "MCQ".
Bullet separators ("•", "··", "・") sit slightly above zero, and text inside URLs
(after "://" or "www") sits slightly below. Everywhere else the program predicts 0;
the component's small, token-specific wiggles are not modelled."""
READS = ()
BULLETS = {"•", "··", "・"}
def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    # the word being spelled, from up to three tokens back, lower-cased
    text = "".join(prefix.token_strings[-3:]).lower()
    if text.endswith("ppt"):
        return None, 0.6
    if text.endswith(("powerpoint", "power point", "handout")):
        return None, 0.5
    if text.endswith(("slide", "slides")):
        return None, 0.4
    if text.endswith("mcq"):
        return None, 0.7
    if cur in BULLETS:
        return None, 0.07
    if text.endswith(("://", "www", "http", "https")):
        return None, -0.08
    return None, 0.0

