import math
import regex

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    q = s.strip()
    new = (len(prefix.document_ids) == 1 or
           prefix.document_ids[-1] != prefix.document_ids[-2])
    letter_tokens = 0 if new or carry is None else carry
    if new:
        if not q:
            value = 4.6 + 0.6 * math.log2(len(s) or 1)
        elif q.startswith('<|'):
            value = 9.4
        elif q.isdigit():
            value = 7.0
        elif regex.fullmatch(r'\p{Script=Han}+', q):
            value = 8.0
        elif any(c.isalpha() for c in q):
            value = 10.0
            if q.isascii():
                value = 10.5
                if not q.isalpha():
                    value = 9.2
                elif q.islower() and len(q) == 2:
                    value = 9.4
                elif q.istitle() and not q.isupper() and len(q) <= 5:
                    value = 11.5
        else:
            value = 5.2 + 1.2 * (min(len(q), 3) - 1)
    elif q == '.' and '\n' not in s:
        prev = prefix.token_strings[-2].strip()
        value = 0.4 * min(1.0, max(0.0, (letter_tokens - 2) / 15))
        if prev.isdigit():
            value = value * 0.45 - 0.03
        elif prev.isupper() or (prev.istitle() and len(prev) < 4):
            value *= 0.2
    elif q in {'。', '、', '，'} and '\n' not in s:
        value = 0.23
    elif q == '=>':
        value = 0.85
    elif q.endswith(',') and any(c in q for c in "\"'}{"):
        value = 0.4
    elif (q.endswith('.') and '\n' not in s and len(q) < 5
          and not any(c.isalnum() for c in q)):
        value = 0.3
    elif q == '.' and '\n' in s:
        value = -0.08
    else:
        value = -0.01
    if any(c in s for c in '.\n;{}') or s in {'。', '！', '？'}:
        letter_tokens = 0
    elif any(c.isalpha() for c in s):
        letter_tokens += 1
    return letter_tokens, value

