"""layers.1.mlp.down_proj:3455: the indentation that opens a line deeper than the line before.

The component responds to whitespace that starts a line, when that line is indented more
than the line before it. A line break counts whether it is a real newline or an escaped
backslash-n (as in code or prose quoted inside a string). Predicted activation:

- indentation right after an escaped line break: 1.0 (0.3 for a single space);
- indentation after a real line break that is deeper than the previous line: 0.65 if the
  previous line ended in an opener (':', '(', '[', '{', '>'), 0.05 if it ended in ';', '+'
  or '*', and 0.35 otherwise;
- a tab right after a number (line-numbered listings): 0.13;
- the first token of each document: 0.13;
- everything else: 0.

On eval rows it explains about 30% of the activation variance, and when put into the
model it moves the next-token distribution about 75% as far as switching the component
off does (kl_fraction 0.75). What it leaves out is small, diffuse activity on ordinary
words and punctuation (about half of the variance) that no simple rule captures.
"""

READS = ()

DOCUMENT_START = 0.13
ESCAPED_BREAK_INDENT = 1.0
SINGLE_SPACE_ESCAPED = 0.3
TAB_AFTER_NUMBER = 0.13
OPENERS = ":([{>"
ENDERS = ";+*"


def _width(ws):
    """Width of an indentation string; a tab counts as four spaces."""
    return sum(4 if ch == "\t" else 1 for ch in ws)


def _fresh(doc):
    return dict(doc=doc, at_start=True, indent=0, prev_indent=0, kind="", end="",
                text_last="", slash=False)


def _break(c, head, kind):
    """A line ends. If it had any text, it becomes the previous line."""
    text = head.strip()
    has_text = (not c["at_start"]) or text != ""
    if has_text:
        c.update(prev_indent=c["indent"], end=(text or c["text_last"])[-1:])
    c.update(at_start=True, indent=0, kind=kind, text_last="", slash=False)
    return c


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or prefix.position == 0 or doc != carry["doc"]
    c = _fresh(doc) if first else dict(carry)
    value = 0.0
    if c["slash"] and token == "n":
        c = _break(c, "", "esc")                      # the n of a backslash-n break
    elif token.endswith("\\n"):
        c = _break(c, token[:-2], "esc")              # a whole backslash-n token
    elif "\n" in token:
        c = _break(c, token.split("\n")[0], "nl")     # a real line break
    else:
        c["slash"] = token.endswith("\\")
        body = token[:-1] if c["slash"] else token
        if body.strip() == "":
            if body and c["at_start"]:                # indentation opening a line
                w = _width(body)
                c["indent"] += w
                if c["kind"] == "esc":
                    value = SINGLE_SPACE_ESCAPED if w == 1 else ESCAPED_BREAK_INDENT
                elif c["kind"] == "nl" and c["indent"] > c["prev_indent"]:
                    if c["end"] and c["end"] in OPENERS:
                        value = 0.65
                    elif c["end"] and c["end"] in ENDERS:
                        value = 0.05
                    else:
                        value = 0.35
            elif body and "\t" in body and c["text_last"].isdigit():
                value = TAB_AFTER_NUMBER              # tab after a line number
        else:
            c.update(at_start=False, text_last=body.strip()[-1:])
    if first:
        value = DOCUMENT_START
    return c, value
